"use client";

import React, { useState } from "react";
import { Sidebar } from "@/components/layout/sidebar";
import {
  Search,
  Bell,
  User,
  Calendar,
  Layers,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Terminal,
  FileCode,
  CheckCircle2,
  FileText,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";

interface AuditEntry {
  id: string;
  timestamp: string;
  candidateInitials: string;
  candidateName: string;
  jobRole: string;
  jobReq: string;
  model: string;
  tokens: string;
  latency: string;
  status: "OK" | "WARNING" | "FAILED";
  promptTokens: number;
  responseTokens: number;
  promptText: string;
  responseText: string;
  rationale: string;
}

const MOCK_AUDIT_LOGS: AuditEntry[] = [];

export default function AuditLogPage() {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [selectedRange, setSelectedRange] = useState("Last 24 Hours");
  const [selectedModel, setSelectedModel] = useState("All Models");
  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);

  const toggleRow = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
  };

  const filteredLogs = MOCK_AUDIT_LOGS.filter(
    (log) =>
      log.candidateName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      log.jobRole.toLowerCase().includes(searchQuery.toLowerCase()) ||
      log.jobReq.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="min-h-screen flex bg-[#faf9f6] text-zinc-900 font-sans antialiased">
      <Sidebar />

      <div className="flex-1 flex flex-col min-w-0">
        {/* Header */}
        <header className="h-16 px-8 flex items-center justify-between border-b border-zinc-200/70 bg-white sticky top-0 z-20">
          <div className="flex items-center gap-2 text-xs text-zinc-400 font-bold uppercase tracking-wider">
            <span>ATS</span>
            <span>›</span>
            <span className="text-zinc-900">CANDIDATES</span>
          </div>

          <div className="flex items-center gap-4">
            <div className="relative w-64">
              <Search className="w-4 h-4 text-zinc-400 absolute left-3 top-1/2 -translate-y-1/2" />
              <input
                type="text"
                placeholder="Search candidates..."
                className="w-full h-9 pl-9 pr-3 text-xs bg-zinc-50 rounded-xl border border-zinc-200 focus:outline-none focus:ring-1 focus:ring-zinc-400 placeholder:text-zinc-400 text-zinc-900"
              />
            </div>

            <button className="p-2 rounded-xl text-zinc-500 hover:text-zinc-900 hover:bg-zinc-100 transition-colors">
              <Bell className="w-4 h-4" />
            </button>

            <div className="w-8 h-8 rounded-full bg-black text-white flex items-center justify-center cursor-pointer">
              <User className="w-4 h-4 text-white" />
            </div>
          </div>
        </header>

        {/* Main Content */}
        <main className="flex-1 p-8 max-w-[1300px] w-full mx-auto space-y-6">
          {/* Title and Subtitle */}
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-zinc-950">
              Audit & Compliance
            </h1>
            <p className="text-xs text-zinc-500 font-medium mt-1">
              Immutable record of every AI scoring decision — prompts, tokens,
              rationale.
            </p>
          </div>

          {/* Filter Toolbar */}
          <div className="bg-white rounded-2xl border border-zinc-200/80 p-3 shadow-xs flex flex-col md:flex-row items-center justify-between gap-3">
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
              {/* Date Filter */}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-9 px-3.5 text-xs font-semibold bg-zinc-50 border-zinc-200 rounded-xl gap-2 hover:bg-zinc-100"
                  >
                    <Calendar className="w-3.5 h-3.5 text-zinc-500" />
                    <span>{selectedRange}</span>
                    <ChevronDown className="w-3.5 h-3.5 text-zinc-400" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start" className="bg-white rounded-xl">
                  {["Last 24 Hours", "Last 7 Days", "Last 30 Days"].map((r) => (
                    <DropdownMenuItem
                      key={r}
                      onClick={() => setSelectedRange(r)}
                      className="text-xs cursor-pointer"
                    >
                      {r}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>

              {/* Model Filter */}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-9 px-3.5 text-xs font-semibold bg-zinc-50 border-zinc-200 rounded-xl gap-2 hover:bg-zinc-100"
                  >
                    <Layers className="w-3.5 h-3.5 text-zinc-500" />
                    <span>{selectedModel}</span>
                    <ChevronDown className="w-3.5 h-3.5 text-zinc-400" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start" className="bg-white rounded-xl">
                  {["All Models", "gemma2:2b", "claude-3-5-sonnet", "gpt-4o"].map(
                    (m) => (
                      <DropdownMenuItem
                        key={m}
                        onClick={() => setSelectedModel(m)}
                        className="text-xs cursor-pointer"
                      >
                        {m}
                      </DropdownMenuItem>
                    )
                  )}
                </DropdownMenuContent>
              </DropdownMenu>

              {/* Search Bar */}
              <div className="relative flex-1 md:w-72">
                <Search className="w-4 h-4 text-zinc-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search by Candidate or REQ..."
                  className="w-full h-9 pl-9 pr-3 text-xs bg-zinc-50 rounded-xl border border-zinc-200 focus:outline-none focus:ring-1 focus:ring-zinc-400 placeholder:text-zinc-400 text-zinc-900"
                />
              </div>
            </div>

            {/* Export Log */}
            <Button
              size="sm"
              className="h-9 px-4 text-xs font-semibold bg-black hover:bg-zinc-800 text-white hover:text-zinc-300 rounded-xl shadow-xs cursor-pointer shrink-0 transition-colors"
            >
              Export Log
            </Button>
          </div>

          {/* Audit Trail Table */}
          <div className="bg-white rounded-2xl border border-zinc-200/80 overflow-hidden shadow-xs">
            {/* Table Headers */}
            <div className="grid grid-cols-12 gap-3 px-6 py-3.5 border-b border-zinc-100 text-[11px] font-bold text-zinc-400 uppercase tracking-wider bg-zinc-50/50">
              <div className="col-span-2">TIMESTAMP (UTC)</div>
              <div className="col-span-3">CANDIDATE</div>
              <div className="col-span-3">JOB CONTEXT</div>
              <div className="col-span-1">MODEL</div>
              <div className="col-span-1 text-right">TOKENS</div>
              <div className="col-span-1 text-right">LATENCY</div>
              <div className="col-span-1 text-right pr-2">STATUS</div>
            </div>

            {/* Audit Log Rows / Empty State */}
            {filteredLogs.length === 0 ? (
              <div className="p-12 text-center text-xs text-zinc-400 space-y-2">
                <p className="font-semibold text-zinc-700">No Audit Records</p>
                <p>Scoring prompts and LLM rationale logs will be recorded here when candidates are evaluated.</p>
              </div>
            ) : (
              filteredLogs.map((log) => {
                const isExpanded = expandedId === log.id;

                return (
                  <div key={log.id} className="border-b border-zinc-100 last:border-0">
                  {/* Row Summary */}
                  <div
                    onClick={() => toggleRow(log.id)}
                    className="grid grid-cols-12 gap-3 px-6 py-4 items-center hover:bg-zinc-50/70 transition-colors cursor-pointer text-xs"
                  >
                    <div className="col-span-2 font-mono text-zinc-500 text-[11px]">
                      {log.timestamp}
                    </div>

                    <div className="col-span-3 flex items-center gap-2.5">
                      <div className="w-8 h-8 rounded-full bg-[#eae7df] text-zinc-900 font-bold text-xs flex items-center justify-center shrink-0">
                        {log.candidateInitials}
                      </div>
                      <span className="font-bold text-zinc-950">
                        {log.candidateName}
                      </span>
                    </div>

                    <div className="col-span-3">
                      <p className="font-semibold text-zinc-900 leading-tight">
                        {log.jobRole}
                      </p>
                      <span className="text-[10px] text-zinc-400 font-mono">
                        {log.jobReq}
                      </span>
                    </div>

                    <div className="col-span-1">
                      <span className="bg-zinc-100 text-zinc-700 text-[10px] font-mono px-2 py-0.5 rounded-md border border-zinc-200">
                        {log.model}
                      </span>
                    </div>

                    <div className="col-span-1 text-right font-mono text-zinc-600">
                      {log.tokens}
                    </div>

                    <div className="col-span-1 text-right font-mono text-zinc-600">
                      {log.latency}
                    </div>

                    <div className="col-span-1 flex items-center justify-end gap-1.5 pr-2">
                      <span className="inline-flex items-center gap-1 text-[11px] font-bold text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-md">
                        <span className="w-1.5 h-1.5 rounded-full bg-emerald-600" />
                        <span>{log.status}</span>
                      </span>
                    </div>
                  </div>

                  {/* Expanded Audit Log Details Panel */}
                  {isExpanded && (
                    <div className="px-6 pb-6 pt-3 bg-[#fbfbfa] border-t border-zinc-100 space-y-4 animate-in fade-in-50 duration-150">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {/* Prompt Sent Box */}
                        <div className="bg-white rounded-xl border border-zinc-200 p-4 space-y-2 shadow-2xs">
                          <div className="flex items-center justify-between text-xs font-bold text-zinc-800">
                            <div className="flex items-center gap-1.5">
                              <Terminal className="w-3.5 h-3.5 text-zinc-500" />
                              <span>PROMPT SENT</span>
                            </div>
                            <span className="bg-zinc-100 text-zinc-600 text-[10px] font-mono px-2 py-0.5 rounded-md">
                              {log.promptTokens.toLocaleString()} tokens
                            </span>
                          </div>
                          <pre className="text-[11px] font-mono text-zinc-700 bg-zinc-50/80 p-3 rounded-lg overflow-x-auto whitespace-pre-wrap leading-relaxed">
                            {log.promptText}
                          </pre>
                        </div>

                        {/* LLM Response Box */}
                        <div className="bg-white rounded-xl border border-zinc-200 p-4 space-y-2 shadow-2xs">
                          <div className="flex items-center justify-between text-xs font-bold text-zinc-800">
                            <div className="flex items-center gap-1.5">
                              <FileCode className="w-3.5 h-3.5 text-zinc-500" />
                              <span>LLM RESPONSE</span>
                            </div>
                            <span className="bg-zinc-100 text-zinc-600 text-[10px] font-mono px-2 py-0.5 rounded-md">
                              {log.responseTokens.toLocaleString()} tokens
                            </span>
                          </div>
                          <pre className="text-[11px] font-mono text-zinc-700 bg-zinc-50/80 p-3 rounded-lg overflow-x-auto whitespace-pre-wrap leading-relaxed">
                            {log.responseText}
                          </pre>
                        </div>
                      </div>

                      {/* Scoring Rationale */}
                      <div className="bg-white rounded-xl border border-zinc-200 p-4 space-y-1.5 shadow-2xs">
                        <div className="flex items-center gap-1.5 text-xs font-bold text-zinc-800">
                          <FileText className="w-3.5 h-3.5 text-zinc-500" />
                          <span>SCORING RATIONALE</span>
                        </div>
                        <p className="text-xs text-zinc-600 leading-relaxed">
                          {log.rationale}
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              );
            })
          )}
          </div>

          {/* Pagination Footer */}
          <div className="flex items-center justify-between text-xs text-zinc-500 font-medium px-2">
            <span>Showing 1–20 of 1,284 records</span>

            <div className="flex items-center gap-1">
              <button className="w-8 h-8 rounded-lg border border-zinc-200 bg-white flex items-center justify-center hover:bg-zinc-50 disabled:opacity-50">
                <ChevronLeft className="w-4 h-4" />
              </button>
              <button className="w-8 h-8 rounded-lg bg-black text-white hover:text-zinc-300 font-bold flex items-center justify-center transition-colors">
                1
              </button>
              <button className="w-8 h-8 rounded-lg border border-zinc-200 bg-white flex items-center justify-center hover:bg-zinc-50">
                2
              </button>
              <button className="w-8 h-8 rounded-lg border border-zinc-200 bg-white flex items-center justify-center hover:bg-zinc-50">
                3
              </button>
              <span className="px-1 text-zinc-400">...</span>
              <button className="w-8 h-8 rounded-lg border border-zinc-200 bg-white flex items-center justify-center hover:bg-zinc-50">
                65
              </button>
              <button className="w-8 h-8 rounded-lg border border-zinc-200 bg-white flex items-center justify-center hover:bg-zinc-50">
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { Sidebar } from "@/components/layout/sidebar";
import {
  Search,
  Bell,
  ArrowLeft,
  MapPin,
  ChevronDown,
  Sparkles,
  Check,
  Plus,
  Users,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { fetchCandidates, fetchJobs, addJobCandidate, getErrorMessage } from "@/lib/api";
import { JobRequisition } from "@/types/ats";

interface TalentCandidate {
  id: string;
  name: string;
  role: string;
  location: string;
  matchScore: number | null;
  skills: string[];
  avatar: string;
  experienceYears: number;
  status: "Active" | "Placed";
}

const TALENT_POOL: TalentCandidate[] = [];

export default function CandidatesPage() {
  const [candidatesList, setCandidatesList] = useState<TalentCandidate[]>([]);
  const [availableJobs, setAvailableJobs] = useState<JobRequisition[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchMode, setSearchMode] = useState<"Hybrid" | "Semantic" | "Keyword">("Hybrid");
  const [selectedSkills, setSelectedSkills] = useState<string[]>([]);
  const [selectedExp, setSelectedExp] = useState<string>("");
  const [selectedStatus, setSelectedStatus] = useState<string[]>([]);
  const [sortBy, setSortBy] = useState("Relevance");
  const [addedJobs, setAddedJobs] = useState<Record<string, string>>({});

  React.useEffect(() => {
    async function loadData() {
      try {
        const [liveData, jobsData] = await Promise.all([
          fetchCandidates(),
          fetchJobs(),
        ]);

        if (jobsData && jobsData.length > 0) {
          setAvailableJobs(jobsData.slice(0, 20));
        }

        if (liveData && liveData.length > 0) {
          const liveMapped: TalentCandidate[] = liveData.map((d) => ({
            id: d.id,
            name: d.name || "Candidate",
            role: d.target_headline || d.role || "Software Engineer",
            location: d.location || "Remote",
            matchScore: d.scorecard?.overall_match_score ?? null,
            skills: d.core_skills || [],
            avatar: d.avatar || (d.name ? d.name.slice(0, 2).toUpperCase() : "CD"),
            experienceYears: Math.round(d.years_of_experience || 0),
            status: "Active",
          }));
          setCandidatesList(liveMapped);
        } else {
          setCandidatesList([]);
        }
      } catch (err) {
        setError(getErrorMessage(err));
      }
    }
    loadData();
  }, []);

  const handleAddCandidateToJob = async (cand: TalentCandidate, job: JobRequisition) => {
    try {
      await addJobCandidate(job.id, {
        id: cand.id,
        name: cand.name || "Candidate",
        headline: cand.role || "Software Engineer",
        avatar: cand.avatar,
        isImageAvatar: Boolean(cand.avatar && typeof cand.avatar === "string" && cand.avatar.startsWith("http")),
        matchScore: null,
        skills: cand.skills || [],
        stage: "Screening",
      });
      setAddedJobs((prev) => ({
        ...prev,
        [cand.id]: `Added to ${(job.title || "Job").split(" ")[0]} ✓`,
      }));
    } catch (err) {
      setError(getErrorMessage(err));
    }
  };

  const toggleSkill = (skill: string) => {
    setSelectedSkills((prev) =>
      prev.includes(skill) ? prev.filter((s) => s !== skill) : [...prev, skill]
    );
  };

  const toggleStatus = (st: string) => {
    setSelectedStatus((prev) =>
      prev.includes(st) ? prev.filter((s) => s !== st) : [...prev, st]
    );
  };

  const clearFilters = () => {
    setSelectedSkills([]);
    setSelectedExp("");
    setSelectedStatus([]);
    setSearchQuery("");
  };

  const filteredCandidates = candidatesList.filter((c) => {
    const q = searchQuery.toLowerCase();
    const nameMatch = (c.name || "").toLowerCase().includes(q);
    const roleMatch = (c.role || "").toLowerCase().includes(q);
    const skillMatch = (c.skills || []).some((s) => (s || "").toLowerCase().includes(q));

    const matchesSearch = !searchQuery || nameMatch || roleMatch || skillMatch;

    const matchesStatus =
      selectedStatus.length === 0 || selectedStatus.includes(c.status);

    return matchesSearch && matchesStatus;
  });

  return (
    <div className="min-h-screen flex bg-[#faf9f6] text-zinc-900 font-sans antialiased">
      <Sidebar />

      <div className="flex-1 flex flex-col min-w-0">
        {/* Top Header */}
        <header className="h-16 px-8 flex items-center justify-between border-b border-zinc-200/70 bg-white sticky top-0 z-20">
          <div className="flex items-center gap-3 text-xs text-zinc-500 font-medium">
            <Link
              href="/jobs"
              className="p-1 rounded-lg hover:bg-zinc-100 text-zinc-700 transition-colors"
            >
              <ArrowLeft className="w-4 h-4" />
            </Link>
            <Link href="/jobs" className="hover:text-zinc-900">
              Jobs
            </Link>
            <span>›</span>
            <span className="text-zinc-900 font-semibold">
              Talent Candidates Directory
            </span>
          </div>

          <div className="flex items-center gap-3">
            <button className="p-2 rounded-xl text-zinc-500 hover:text-zinc-900 hover:bg-zinc-100 transition-colors">
              <Search className="w-4 h-4" />
            </button>
            <button className="p-2 rounded-xl text-zinc-500 hover:text-zinc-900 hover:bg-zinc-100 transition-colors">
              <Bell className="w-4 h-4" />
            </button>
          </div>
        </header>

        {/* Main Content */}
        <main className="flex-1 p-8 max-w-[1300px] w-full mx-auto space-y-8">
          {error && <p role="alert" className="text-red-700">{error}</p>}
          {/* Central Search Bar & Mode Selector */}
          <div className="flex flex-col items-center gap-4 max-w-2xl mx-auto pt-2">
            <div className="relative w-full shadow-sm">
              <Search className="w-4 h-4 text-zinc-400 absolute left-4 top-1/2 -translate-y-1/2" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search by skills, titles, companies..."
                className="w-full h-12 pl-11 pr-4 text-sm bg-white rounded-full border border-zinc-200/80 shadow-xs focus:ring-2 focus:ring-zinc-900 focus:outline-none transition-all placeholder:text-zinc-400 text-zinc-900"
              />
            </div>

            {/* Mode Pills */}
            <div className="flex flex-col items-center gap-1.5">
              <div className="flex items-center gap-1.5 bg-[#f0eee9] p-1 rounded-full text-xs font-semibold">
                {(["Hybrid", "Semantic", "Keyword"] as const).map((mode) => (
                  <button
                    key={mode}
                    onClick={() => setSearchMode(mode)}
                    className={cn(
                      "px-4 py-1.5 rounded-full transition-all cursor-pointer",
                      searchMode === mode
                        ? "bg-black text-white hover:text-zinc-300 shadow-xs"
                        : "text-zinc-600 hover:text-zinc-950"
                    )}
                  >
                    {mode}
                  </button>
                ))}
              </div>
              <span className="text-[10px] tracking-wider text-zinc-400 font-bold uppercase">
                DENSE + BM25 + RECIPROCAL RANK FUSION
              </span>
            </div>
          </div>

          {/* Main Layout: Left Filters + Right Results */}
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 pt-4">
            {/* Left Filter Sidebar */}
            <aside className="lg:col-span-3 space-y-6 bg-white/70 backdrop-blur-xs p-6 rounded-2xl border border-zinc-200/70 h-fit">
              {/* Skills */}
              <div className="space-y-3">
                <span className="text-xs font-bold tracking-wider text-zinc-900 uppercase">
                  SKILLS
                </span>
                <div className="space-y-2 text-xs">
                  {[
                    { label: "Python", count: 42 },
                    { label: "Kubernetes", count: 18 },
                    { label: "Go", count: 9 },
                    { label: "Rust", count: 4 },
                  ].map(({ label, count }) => {
                    const isChecked = selectedSkills.includes(label);
                    return (
                      <label
                        key={label}
                        className="flex items-center justify-between cursor-pointer group select-none"
                        onClick={() => toggleSkill(label)}
                      >
                        <div className="flex items-center gap-2.5">
                          <div
                            className={cn(
                              "w-4 h-4 rounded flex items-center justify-center transition-colors",
                              isChecked
                                ? "bg-black text-white"
                                : "border border-zinc-300 group-hover:border-zinc-400 bg-white"
                            )}
                          >
                            {isChecked && <Check className="w-3 h-3 stroke-[3]" />}
                          </div>
                          <span
                            className={cn(
                              "font-medium",
                              isChecked ? "text-zinc-950" : "text-zinc-600"
                            )}
                          >
                            {label}
                          </span>
                        </div>
                        <span className="text-[11px] text-zinc-400">{count}</span>
                      </label>
                    );
                  })}
                </div>
              </div>

              {/* Experience */}
              <div className="space-y-3 pt-4 border-t border-zinc-100">
                <span className="text-xs font-bold tracking-wider text-zinc-900 uppercase">
                  EXPERIENCE
                </span>
                <div className="grid grid-cols-4 gap-1.5">
                  {["0–2", "3–5", "6–10", "10+"].map((exp) => (
                    <button
                      key={exp}
                      onClick={() =>
                        setSelectedExp(selectedExp === exp ? "" : exp)
                      }
                      className={cn(
                        "py-1.5 text-xs font-semibold rounded-xl transition-all cursor-pointer",
                        selectedExp === exp
                          ? "bg-black text-white hover:text-zinc-300"
                          : "bg-zinc-100 text-zinc-700 hover:bg-zinc-200"
                      )}
                    >
                      {exp}
                    </button>
                  ))}
                </div>
              </div>

              {/* Status */}
              <div className="space-y-3 pt-4 border-t border-zinc-100">
                <span className="text-xs font-bold tracking-wider text-zinc-900 uppercase">
                  STATUS
                </span>
                <div className="space-y-2 text-xs">
                  {["Active", "Placed"].map((st) => {
                    const isChecked = selectedStatus.includes(st);
                    return (
                      <label
                        key={st}
                        className="flex items-center gap-2.5 cursor-pointer group select-none"
                        onClick={() => toggleStatus(st)}
                      >
                        <div
                          className={cn(
                            "w-4 h-4 rounded flex items-center justify-center transition-colors",
                            isChecked
                              ? "bg-black text-white"
                              : "border border-zinc-300 group-hover:border-zinc-400 bg-white"
                          )}
                        >
                          {isChecked && <Check className="w-3 h-3 stroke-[3]" />}
                        </div>
                        <span
                          className={cn(
                            "font-medium",
                            isChecked ? "text-zinc-950" : "text-zinc-600"
                          )}
                        >
                          {st}
                        </span>
                      </label>
                    );
                  })}
                </div>
              </div>

              {/* Clear filters */}
              <button
                onClick={clearFilters}
                className="text-xs text-zinc-500 hover:text-zinc-950 font-medium underline underline-offset-4 cursor-pointer pt-2 block"
              >
                Clear filters
              </button>
            </aside>

            {/* Right Candidates Results Grid */}
            <div className="lg:col-span-9 space-y-5">
              {/* Results count & Sort */}
              <div className="flex items-center justify-between text-xs text-zinc-500 font-bold uppercase tracking-wider px-1">
                <span>89 RESULTS · 24MS</span>
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <button className="flex items-center gap-1 text-zinc-700 font-semibold cursor-pointer hover:text-zinc-950">
                      <span>Sort by: {sortBy}</span>
                      <ChevronDown className="w-3.5 h-3.5" />
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="bg-white rounded-xl">
                    {["Relevance", "Highest Match", "Experience", "Newest"].map(
                      (opt) => (
                        <DropdownMenuItem
                          key={opt}
                          onClick={() => setSortBy(opt)}
                          className="text-xs cursor-pointer"
                        >
                          {opt}
                        </DropdownMenuItem>
                      )
                    )}
                  </DropdownMenuContent>
                </DropdownMenu>
              </div>

              {/* Grid of Candidate Cards / Empty State */}
              {filteredCandidates.length === 0 ? (
                <div className="bg-white rounded-2xl border border-dashed border-zinc-200 p-12 text-center space-y-4">
                  <div className="w-12 h-12 rounded-full bg-zinc-100 text-zinc-400 flex items-center justify-center mx-auto">
                    <Users className="w-6 h-6" />
                  </div>
                  <div>
                    <h3 className="font-bold text-base text-zinc-900">
                      No Candidates Found
                    </h3>
                    <p className="text-xs text-zinc-500 max-w-md mx-auto mt-1">
                      No candidates currently match your filters or talent pool is empty. Upload candidate resumes to start scoring.
                    </p>
                  </div>
                  <Link href="/upload" className="inline-block">
                    <Button
                      size="sm"
                      className="bg-black hover:bg-zinc-800 text-white text-xs font-semibold rounded-full px-5 h-9 transition-colors"
                    >
                      Upload Resumes
                    </Button>
                  </Link>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {filteredCandidates.map((cand) => (
                    <div
                      key={cand.id}
                      className="bg-white rounded-2xl border border-zinc-200/80 p-5 shadow-xs hover:border-zinc-300 hover:shadow-md transition-all flex flex-col justify-between min-h-[220px]"
                    >
                      <div>
                        {/* Top: Avatar, Name, Location, Match % */}
                        <div className="flex items-start justify-between gap-3">
                          <div className="flex items-center gap-3">
                            {cand.avatar && typeof cand.avatar === "string" && cand.avatar.startsWith("http") ? (
                              <img
                                src={cand.avatar}
                                alt={cand.name || "Candidate"}
                                className="w-12 h-12 rounded-full object-cover border border-zinc-200 shrink-0"
                              />
                            ) : (
                              <div className="w-12 h-12 rounded-full bg-[#eae7df] text-zinc-900 font-bold text-sm flex items-center justify-center shrink-0">
                                {cand.avatar || (cand.name ? cand.name.slice(0, 2).toUpperCase() : "CD")}
                              </div>
                            )}
                            <div>
                              <h3 className="font-bold text-sm text-zinc-950">
                                {cand.name || "Candidate"}
                              </h3>
                              <p className="text-xs text-zinc-500 font-medium leading-tight">
                                {cand.role || "Software Specialist"}
                              </p>
                              <div className="flex items-center gap-1 text-[11px] text-zinc-400 mt-1">
                                <MapPin className="w-3 h-3 text-zinc-400" />
                                <span>{cand.location || "Remote"}</span>
                              </div>
                            </div>
                          </div>

                          {/* Match Score */}
                          <div className="flex flex-col items-end">
                            <span className="text-xl font-bold tracking-tight text-zinc-950 leading-none">
                              {cand.matchScore === null ? "Pending" : `${cand.matchScore}%`}
                            </span>
                            <span className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider">
                              MATCH
                            </span>
                          </div>
                        </div>

                        {/* Skill Tags */}
                        <div className="flex flex-wrap gap-1.5 mt-4">
                          {cand.skills.map((skill) => (
                            <span
                              key={skill}
                              className="bg-[#f4f3ee] text-zinc-800 text-[11px] font-medium px-2.5 py-0.5 rounded-lg border border-zinc-200/60"
                            >
                              {skill}
                            </span>
                          ))}
                        </div>
                      </div>

                      {/* Bottom Action Buttons */}
                      <div className="flex items-center gap-2.5 mt-5 pt-3 border-t border-zinc-100">
                        <Link
                          href={`/candidates/${cand.id}`}
                          className="flex-1"
                        >
                          <Button
                            variant="outline"
                            size="sm"
                            className="w-full text-xs font-semibold rounded-full h-8.5 border-zinc-300 bg-white text-zinc-900 hover:bg-zinc-100 hover:text-zinc-700 shadow-none transition-colors"
                          >
                            View
                          </Button>
                        </Link>

                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button
                              size="sm"
                              className="flex-1 bg-black hover:bg-zinc-800 text-white hover:text-zinc-300 text-xs font-semibold rounded-full h-8.5 gap-1 shadow-none cursor-pointer transition-colors"
                            >
                              <span>
                                {addedJobs[cand.id]
                                  ? addedJobs[cand.id]
                                  : "Add to Job"}
                              </span>
                              <ChevronDown className="w-3.5 h-3.5 text-zinc-300" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent
                            align="end"
                            className="bg-white rounded-xl shadow-lg border border-zinc-200 w-56 max-h-64 overflow-y-auto"
                          >
                            {availableJobs.map((job) => (
                              <DropdownMenuItem
                                key={job.id}
                                onClick={() => handleAddCandidateToJob(cand, job)}
                                className="text-xs cursor-pointer py-2 hover:bg-zinc-50"
                              >
                                <span className="font-semibold truncate">
                                  {job.title}
                                </span>
                              </DropdownMenuItem>
                            ))}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </div>
                  ))}
                </div>
              )}

              {/* Load More Button */}
              <div className="flex justify-center pt-6">
                <Button
                  variant="outline"
                  size="sm"
                  className="rounded-full px-6 text-xs font-semibold border-zinc-300 hover:bg-zinc-100 text-zinc-700 shadow-none"
                >
                  Load More Results
                </Button>
              </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { Sidebar } from "@/components/layout/sidebar";
import {
  ArrowLeft,
  Search,
  Bell,
  RotateCw,
  Edit2,
  Building2,
  Calendar,
  Users,
  Target,
  MessageSquare,
  AlertTriangle,
  ExternalLink,
  MoreVertical,
  Check,
  Briefcase,
  Sparkles,
  ChevronRight,
  Plus,
  ArrowRight,
  X,
  FileText,
  Clock,
  Send,
  UserCheck,
  UserPlus,
  UserMinus,
  Trash2,
  Zap,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { AddCandidateJobModal, NewCandidatePayload } from "@/components/jobs/add-candidate-job-modal";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import {
  fetchJobDetail,
  updateJobRequisition,
  getErrorMessage,
  evaluateJobMatching,
  fetchJobCandidates,
  addJobCandidate,
  removeJobCandidate,
  updateJobCandidateStage,
} from "@/lib/api";
import { JobRequisition, RankedCandidate } from "@/types/ats";

const INITIAL_RANKED_CANDIDATES: RankedCandidate[] = [];

export default function JobPipelineDetailPage() {
  const params = useParams();
  const router = useRouter();
  const rawId = (params?.id as string) || "job-001";

  // Job Requisition State
  const [job, setJob] = useState<JobRequisition | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<
    "AI Ranked List" | "Pipeline Board" | "Job Details" | "Activity"
  >("AI Ranked List");

  // Candidates list state
  const [candidates, setCandidates] = useState<RankedCandidate[]>([]);
  const [expandedCand, setExpandedCand] = useState<string | null>(null);

  // Action states
  const [isReRunning, setIsReRunning] = useState(false);
  const [reRunMessage, setReRunMessage] = useState<string | null>(null);
  const [advancingCandId, setAdvancingCandId] = useState<string | null>(null);
  const [advancedCandidates, setAdvancedCandidates] = useState<
    Record<string, boolean>
  >({});

  // Add Candidate Modal State
  const [isAddCandidateOpen, setIsAddCandidateOpen] = useState(false);

  // Edit Modal State
  const [isEditOpen, setIsEditOpen] = useState(false);
  const [editTitle, setEditTitle] = useState("");
  const [editDepartment, setEditDepartment] = useState("");
  const [editLocation, setEditLocation] = useState("");
  const [editDescription, setEditDescription] = useState("");
  const [editSkills, setEditSkills] = useState<string[]>([]);
  const [newSkillText, setNewSkillText] = useState("");

  useEffect(() => {
    async function loadJobAndCandidates() {
      if (rawId) {
        const jobData = await fetchJobDetail(rawId);
        if (jobData) {
          setJob(jobData);
          setEditTitle(jobData.title);
          setEditDepartment(jobData.department);
          setEditLocation(jobData.location);
          setEditDescription(jobData.job_description);
          setEditSkills(jobData.required_skills);
        }

        const candidateData = await fetchJobCandidates(rawId);
        if (candidateData && candidateData.length > 0) {
          setCandidates(candidateData);
          if (candidateData[0]) {
            setExpandedCand(candidateData[0].id);
          }
        }
      }
    }
    loadJobAndCandidates().catch(reason => setError(getErrorMessage(reason)));
  }, [rawId]);

  const handleReRunMatch = async () => {
    if (!job) return;
    setIsReRunning(true);
    setReRunMessage("Waiting for backend matching...");
    try {
      await evaluateJobMatching({ job_title: job.title, job_description: job.job_description });
      setCandidates(await fetchJobCandidates(rawId));
      setReRunMessage("Matching request completed. Pipeline loaded from the backend.");
      setError(null);
    } catch (reason) { setReRunMessage(null); setError(getErrorMessage(reason)); }
    finally { setIsReRunning(false); }
  };

  const handleAddCandidate = async (payload: NewCandidatePayload) => {
    try {
      const updatedList = await addJobCandidate(rawId, payload);
      setCandidates(updatedList);

      const targetId = payload.sourceResumeLink?.replace("/candidates/", "") || updatedList[0]?.id;
      const matched = updatedList.find((c) => c.name === payload.name) || updatedList[0];

      if (matched) {
        setExpandedCand(matched.id);
      }

      setJob(prev => prev ? { ...prev, candidates_count: updatedList.length } : null);

      const myRank = matched ? matched.rank : 1;
      setReRunMessage(
        `✓ Candidate "${payload.name}" added! Pipeline dynamically re-ranked — Ranked #${myRank} of ${updatedList.length} candidates.`
      );
      setTimeout(() => setReRunMessage(null), 6000);
    } catch (err) {
      setError(getErrorMessage(err));
      throw err;
    }
  };

  const handleRemoveCandidate = async (candId: string) => {
    const candToRemove = candidates.find((c) => c.id === candId);
    const name = candToRemove ? candToRemove.name : "Candidate";

    try {
      const updatedList = await removeJobCandidate(rawId, candId);
      setCandidates(updatedList);
      if (expandedCand === candId) {
        setExpandedCand(updatedList[0]?.id || null);
      }
      setJob(prev => prev ? { ...prev, candidates_count: updatedList.length } : null);

      setReRunMessage(
        `✓ Candidate "${name}" removed from this job. Remaining ${updatedList.length} candidates dynamically re-ranked.`
      );
      setTimeout(() => setReRunMessage(null), 5000);
    } catch (err) {
      setError(getErrorMessage(err));
    }
  };

  const handleAdvanceCandidate = async (candId: string) => {
    setAdvancingCandId(candId);
    const currentCand = candidates.find((c) => c.id === candId);
    if (!currentCand) { setAdvancingCandId(null); return; }

    const nextStage =
      currentCand.stage === "Applied"
        ? "Screening"
        : currentCand.stage === "Screening"
        ? "Interview"
        : currentCand.stage === "Interview"
        ? "Qualified"
        : "Offer";

    try {
      await updateJobCandidateStage(rawId, candId, nextStage);
      setAdvancingCandId(null);
      setAdvancedCandidates((prev) => ({ ...prev, [candId]: true }));
      setCandidates((prev) =>
        prev.map((c) => {
          if (c.id !== candId) return c;
          return {
            ...c,
            stage: nextStage,
            stageBadgeStyle:
              nextStage === "Qualified" || nextStage === "Offer"
                ? "bg-emerald-100 text-emerald-900"
                : "bg-[#ede8dc] text-zinc-800",
          };
        })
      );
    } catch (err) {
      setAdvancingCandId(null);
      setError(getErrorMessage(err));
    }
  };

  const handleSaveJobEdit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setJob(await updateJobRequisition(rawId, { title: editTitle, department: editDepartment, location: editLocation, job_description: editDescription, required_skills: editSkills }));
      setIsEditOpen(false);
      setError(null);
    } catch (reason) { setError(getErrorMessage(reason)); }
  };

  const handleAddSkill = () => {
    if (newSkillText.trim() && !editSkills.includes(newSkillText.trim())) {
      setEditSkills([...editSkills, newSkillText.trim()]);
      setNewSkillText("");
    }
  };

  const handleRemoveSkill = (skillToRemove: string) => {
    setEditSkills(editSkills.filter((s) => s !== skillToRemove));
  };

  if (!job) return <div className="p-8">{error ? <p role="alert" className="text-red-700">{error}</p> : <p role="status">Loading job…</p>}<Link href="/jobs">Back to jobs</Link></div>;

  return (
    <div className="min-h-screen flex bg-[#faf9f6] text-zinc-900 font-sans antialiased">
      {/* Global Sidebar */}
      <Sidebar />

      {/* Main Container */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Top Header Breadcrumb & Actions */}
        <header className="h-16 px-8 flex items-center justify-between border-b border-zinc-200/70 bg-white sticky top-0 z-20">
          <div className="flex items-center gap-3 text-xs text-zinc-500 font-medium">
            <Link
              href="/jobs"
              className="p-1 rounded-lg hover:bg-zinc-100 text-zinc-700 transition-colors"
            >
              <ArrowLeft className="w-4 h-4" />
            </Link>
            <Link href="/jobs" className="hover:text-zinc-900 font-medium">
              Jobs
            </Link>
            <span>›</span>
            <span className="text-zinc-900 font-semibold truncate max-w-xs">
              {job.title}
            </span>
          </div>

          <div className="flex items-center gap-3">
            <button className="p-2 rounded-xl text-zinc-500 hover:text-zinc-900 hover:bg-zinc-100 transition-colors">
              <Search className="w-4 h-4" />
            </button>
            <button className="p-2 rounded-xl text-zinc-500 hover:text-zinc-900 hover:bg-zinc-100 transition-colors">
              <Bell className="w-4 h-4" />
            </button>
          </div>
        </header>

        {/* Main Content Area */}
        <main className="flex-1 p-8 max-w-[1280px] w-full mx-auto space-y-6">
          {error && <p role="alert" className="text-red-700">{error}</p>}
          {/* Re-run notification banner */}
          {reRunMessage && (
            <div className="bg-[#ede8dc] border border-[#dad4c5] text-zinc-900 px-4 py-2.5 rounded-xl text-xs font-semibold flex items-center justify-between animate-in fade-in-50 duration-200">
              <div className="flex items-center gap-2">
                <Sparkles className="w-4 h-4 text-zinc-800" />
                <span>{reRunMessage}</span>
              </div>
              <button
                onClick={() => setReRunMessage(null)}
                className="text-zinc-500 hover:text-zinc-800 p-0.5"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            </div>
          )}

          {/* Job Title & Main Action Header */}
          <div className="space-y-3">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
              <div className="flex items-center gap-3 flex-wrap">
                <h1 className="text-2xl font-bold tracking-tight text-zinc-950">
                  {job.title}
                </h1>
                <span className="bg-[#ede8dc] text-zinc-800 text-[11px] font-bold px-2.5 py-0.5 rounded-full uppercase tracking-wider">
                  {job.status}
                </span>
              </div>

              <div className="flex items-center gap-2.5">
                <Button
                  onClick={() => setIsAddCandidateOpen(true)}
                  size="sm"
                  className="bg-black hover:bg-zinc-800 text-white hover:text-zinc-300 rounded-full px-4 text-xs font-semibold h-9 gap-1.5 shadow-none cursor-pointer transition-colors"
                >
                  <UserPlus className="w-3.5 h-3.5" />
                  <span>Add New Candidate</span>
                </Button>

                <Button
                  onClick={handleReRunMatch}
                  disabled={isReRunning}
                  variant="outline"
                  size="sm"
                  className="rounded-full px-4 text-xs font-semibold h-9 border-zinc-200 hover:bg-zinc-50 gap-1.5 shadow-none cursor-pointer"
                >
                  <RotateCw
                    className={cn(
                      "w-3.5 h-3.5 text-zinc-700",
                      isReRunning && "animate-spin"
                    )}
                  />
                  <span>{isReRunning ? "Evaluating..." : "Re-run Match"}</span>
                </Button>

                <Button
                  onClick={() => setIsEditOpen(true)}
                  size="sm"
                  variant="outline"
                  className="border-zinc-200 hover:bg-zinc-50 rounded-full px-4 text-xs font-semibold h-9 gap-1.5 shadow-none cursor-pointer transition-colors"
                >
                  <Edit2 className="w-3.5 h-3.5" />
                  <span>Edit</span>
                </Button>
              </div>
            </div>

            {/* Job Metadata Bar */}
            <div className="flex flex-wrap items-center gap-4 text-xs text-zinc-500 font-medium">
              <div className="flex items-center gap-1.5">
                <Building2 className="w-3.5 h-3.5 text-zinc-400" />
                <span>{job.department}</span>
              </div>
              <span>•</span>
              <div className="flex items-center gap-1.5">
                <Calendar className="w-3.5 h-3.5 text-zinc-400" />
                <span>Created {job.posted_date}</span>
              </div>
              <span>•</span>
              <div className="flex items-center gap-1.5">
                <Users className="w-3.5 h-3.5 text-zinc-400" />
                <span>{job.candidates_count} Candidates</span>
              </div>
            </div>
          </div>

          {/* Sub Navigation Tabs */}
          <div className="border-b border-zinc-200/80 flex items-center gap-6">
            {[
              { id: "AI Ranked List" as const, label: "AI Ranked List", hasDot: true },
              { id: "Pipeline Board" as const, label: "Pipeline Board" },
              { id: "Job Details" as const, label: "Job Details" },
              { id: "Activity" as const, label: "Activity" },
            ].map((tab) => {
              const isActive = activeTab === tab.id;
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={cn(
                    "pb-3 text-xs font-semibold flex items-center gap-1.5 relative transition-colors cursor-pointer",
                    isActive
                      ? "text-zinc-950 font-bold border-b-2 border-black -mb-[1px]"
                      : "text-zinc-500 hover:text-zinc-800"
                  )}
                >
                  <span>{tab.label}</span>
                  {tab.hasDot && (
                    <span className="w-1.5 h-1.5 rounded-full bg-red-500" />
                  )}
                </button>
              );
            })}
          </div>

          {/* ============================================================ */}
          {/* TAB 1: AI RANKED LIST VIEW (Exact layout as requested) */}
          {/* ============================================================ */}
          {activeTab === "AI Ranked List" && (
            <div className="bg-white rounded-2xl border border-zinc-200/80 overflow-hidden shadow-xs animate-in fade-in-50 duration-150">
              {/* Header Bar with Action */}
              <div className="flex items-center justify-between px-6 py-3 border-b border-zinc-100 bg-white">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-bold text-zinc-900">Ranked Candidates</span>
                  <span className="text-[11px] font-bold bg-[#ede8dc] text-zinc-800 px-2 py-0.5 rounded-full">
                    {candidates.length} in pipeline
                  </span>
                </div>
                <Button
                  onClick={() => setIsAddCandidateOpen(true)}
                  size="sm"
                  variant="outline"
                  className="h-7 text-xs font-semibold rounded-lg px-2.5 gap-1.5 border-zinc-200 hover:bg-zinc-50 cursor-pointer"
                >
                  <UserPlus className="w-3 h-3" />
                  <span>Add Candidate</span>
                </Button>
              </div>

              {/* Table Header */}
              <div className="grid grid-cols-12 gap-4 px-6 py-3.5 border-b border-zinc-100 text-[11px] font-bold text-zinc-400 uppercase tracking-wider bg-zinc-50/50">
                <div className="col-span-1 text-center">#</div>
                <div className="col-span-4">CANDIDATE</div>
                <div className="col-span-3">AI MATCH SCORE</div>
                <div className="col-span-2">KEY SKILLS EXTRACTION</div>
                <div className="col-span-2 text-right pr-4">STAGE</div>
              </div>

              {/* Candidates Rows / Empty State */}
              {candidates.length === 0 ? (
                <div className="p-12 text-center space-y-4">
