"use client";

import React, { useState, useEffect, useCallback } from "react";
import {
  Layers,
  Sparkles,
  CheckCircle2,
  XCircle,
  Plus,
  Search,
  RefreshCw,
  Database,
  Tag,
  ShieldCheck,
  AlertCircle,
  HelpCircle,
  ArrowRight,
  TrendingUp,
  FileCode,
  Globe,
  SlidersHorizontal,
} from "lucide-react";
import { Sidebar } from "@/components/layout/sidebar";
import { TopNav } from "@/components/layout/top-nav";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  fetchTaxonomyStats,
  fetchTaxonomySkills,
  approveTaxonomySkill,
  rejectTaxonomySkill,
  addAliasToTaxonomySkill,
  createTaxonomySkill,
  TaxonomySkillItem,
  TaxonomyStats,
  getErrorMessage,
} from "@/lib/api";
import { cn } from "@/lib/utils";

const CATEGORIES = [
  { id: "all", label: "All Categories" },
  { id: "language", label: "Languages" },
  { id: "framework", label: "Frameworks" },
  { id: "database", label: "Databases" },
  { id: "platform", label: "Cloud & Platforms" },
  { id: "tool", label: "Tools & DevOps" },
  { id: "library", label: "AI/ML & Libraries" },
  { id: "domain", label: "Domains & Architecture" },
  { id: "soft_skill", label: "Soft Skills" },
];

export default function TaxonomyPage() {
  const [error, setError] = useState<string | null>(null);
  const [stats, setStats] = useState<TaxonomyStats | null>(null);
  const [skills, setSkills] = useState<TaxonomySkillItem[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [loading, setLoading] = useState(true);

  // Filters
  const [activeTab, setActiveTab] = useState<"all" | "approved" | "pending" | "rejected">("pending");
  const [selectedCategory, setSelectedCategory] = useState("all");
  const [searchQuery, setSearchQuery] = useState("");

  // Modals
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [newCanonicalName, setNewCanonicalName] = useState("");
  const [newCategory, setNewCategory] = useState("language");
  const [newAliases, setNewAliases] = useState("");
  const [newIsAmbiguous, setNewIsAmbiguous] = useState(false);

  const [aliasModalTarget, setAliasModalTarget] = useState<TaxonomySkillItem | null>(null);
  const [newAliasInput, setNewAliasInput] = useState("");

  const loadData = useCallback(async () => {
    try {
      const [statsData, skillsData] = await Promise.all([
        fetchTaxonomyStats(),
        fetchTaxonomySkills({
          category: selectedCategory !== "all" ? selectedCategory : undefined,
          status: activeTab !== "all" ? activeTab : undefined,
          search: searchQuery || undefined,
          limit: 100,
        }),
      ]);
      setError(null);
      setStats(statsData);
      setSkills(skillsData.items);
      setTotalCount(skillsData.total);

      // If no pending items on first load and tab was pending, switch to approved
      if (activeTab === "pending" && skillsData.total === 0 && !searchQuery) {
        setActiveTab("approved");
      }
    } catch (e) {
      setError(getErrorMessage(e));
    } finally {
      setLoading(false);
    }
  }, [activeTab, selectedCategory, searchQuery]);

  useEffect(() => { void loadData(); }, [loadData]);

  const handleApprove = async (skill: TaxonomySkillItem) => {
    try { await approveTaxonomySkill(skill.id); await loadData(); }
    catch (reason) { setError(getErrorMessage(reason)); }
  };

  const handleReject = async (skill: TaxonomySkillItem) => {
    try { await rejectTaxonomySkill(skill.id); await loadData(); }
    catch (reason) { setError(getErrorMessage(reason)); }
  };

  const handleCreateSkill = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCanonicalName.trim()) return;

    const aliasesArr = newAliases
      .split(",")
      .map((a) => a.trim())
      .filter(Boolean);

    try {
    await createTaxonomySkill({
      canonical_name: newCanonicalName.trim(),
      category: newCategory,
      aliases: aliasesArr,
      is_ambiguous: newIsAmbiguous,
      source: "manual",
    });

    setIsAddModalOpen(false);
    setNewCanonicalName("");
    setNewAliases("");
    setNewIsAmbiguous(false);
    await loadData();
    } catch (reason) { setError(getErrorMessage(reason)); }
  };

  const handleAddAliasSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!aliasModalTarget || !newAliasInput.trim()) return;

    try {
    await addAliasToTaxonomySkill(aliasModalTarget.id, newAliasInput.trim());
    setAliasModalTarget(null);
    setNewAliasInput("");
    await loadData();
    } catch (reason) { setError(getErrorMessage(reason)); }
  };

  const getCategoryBadgeColor = (category: string) => {
    switch (category) {
      case "language":
        return "bg-blue-50 text-blue-700 border-blue-200/80";
      case "framework":
        return "bg-purple-50 text-purple-700 border-purple-200/80";
      case "database":
        return "bg-amber-50 text-amber-700 border-amber-200/80";
      case "platform":
        return "bg-emerald-50 text-emerald-700 border-emerald-200/80";
      case "tool":
        return "bg-zinc-100 text-zinc-800 border-zinc-200";
      case "library":
        return "bg-rose-50 text-rose-700 border-rose-200/80";
      case "domain":
        return "bg-indigo-50 text-indigo-700 border-indigo-200/80";
      default:
        return "bg-zinc-50 text-zinc-600 border-zinc-200";
    }
  };

  return (
    <div className="min-h-screen flex bg-[#faf9f6]">
      <Sidebar />

      <div className="flex-1 flex flex-col min-w-0">
        <TopNav showDateFilter={false} searchPlaceholder="Search skills, aliases, categories..." />

        <main className="flex-1 p-8 max-w-7xl w-full mx-auto space-y-7">
          {error && <p role="alert" className="text-red-700">{error}</p>}
          {/* Header & Title */}
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <div className="flex items-center gap-3">
                <h1 className="text-2xl font-serif font-black text-zinc-950 tracking-tight">
                  Skill Taxonomy & Flywheel
                </h1>
                <Badge
                  variant="outline"
                  className="bg-emerald-50 text-emerald-800 border-emerald-300 font-mono text-[11px] px-2.5 py-0.5 rounded-full"
                >
                  Version v{stats?.version || "2026.08.1"}
                </Badge>
              </div>
              <p className="text-xs text-zinc-500 font-medium mt-1">
                Proprietary ontology mapping ~500+ tech skills with alias normalization, Lightcast / ESCO source grounding, and continuous candidate flywheel learning.
              </p>
            </div>

            <div className="flex items-center gap-2.5">
              <Button
                variant="outline"
                size="sm"
                onClick={loadData}
                className="h-9 px-3.5 text-xs font-semibold rounded-full border-zinc-200 hover:bg-white text-zinc-700 transition-colors flex items-center gap-1.5"
              >
                <RefreshCw className="w-3.5 h-3.5 text-zinc-500" />
                Refresh
              </Button>
              <Button
                size="sm"
                onClick={() => setIsAddModalOpen(true)}
                className="h-9 px-4 text-xs font-semibold rounded-full bg-black hover:bg-zinc-800 text-white transition-colors flex items-center gap-1.5 shadow-xs"
              >
                <Plus className="w-3.5 h-3.5" />
                Add Canonical Skill
              </Button>
            </div>
          </div>

          {/* Metric Overview Cards */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="bg-white p-5 rounded-2xl border border-zinc-200/80 shadow-2xs space-y-1">
              <div className="flex items-center justify-between text-zinc-400">
                <span className="text-[11px] font-bold tracking-wider uppercase text-zinc-500">
                  Total Ontology
                </span>
                <Database className="w-4 h-4 text-zinc-400" />
              </div>
              <div className="text-2xl font-serif font-black text-zinc-950">
                {stats?.total_skills ?? 0}
              </div>
              <p className="text-[11px] text-zinc-400 font-medium">Standardized skill entities</p>
            </div>

            <div className="bg-white p-5 rounded-2xl border border-zinc-200/80 shadow-2xs space-y-1">
              <div className="flex items-center justify-between text-zinc-400">
                <span className="text-[11px] font-bold tracking-wider uppercase text-zinc-500">
                  Approved Canonical
                </span>
                <CheckCircle2 className="w-4 h-4 text-emerald-600" />
              </div>
              <div className="text-2xl font-serif font-black text-emerald-950">
                {stats?.approved_count ?? 0}
              </div>
              <p className="text-[11px] text-emerald-700 font-medium">Production active matching</p>
            </div>

            <div className="bg-white p-5 rounded-2xl border border-amber-200/80 bg-amber-50/20 shadow-2xs space-y-1">
              <div className="flex items-center justify-between text-amber-600">
                <span className="text-[11px] font-bold tracking-wider uppercase text-amber-700">
                  Flywheel Review Queue
                </span>
                <Sparkles className="w-4 h-4 text-amber-500" />
              </div>
              <div className="text-2xl font-serif font-black text-amber-950">
                {stats?.pending_count ?? 0}
              </div>
              <p className="text-[11px] text-amber-700 font-medium">Unmapped candidate skills</p>
            </div>

            <div className="bg-white p-5 rounded-2xl border border-zinc-200/80 shadow-2xs space-y-1">
              <div className="flex items-center justify-between text-zinc-400">
                <span className="text-[11px] font-bold tracking-wider uppercase text-zinc-500">
                  Curated Sources
                </span>
                <Globe className="w-4 h-4 text-indigo-500" />
              </div>
              <div className="text-2xl font-serif font-black text-zinc-950">
                Lightcast + ESCO
              </div>
              <p className="text-[11px] text-zinc-400 font-medium">O*NET & StackOverflow</p>
            </div>
          </div>

          {/* Filter Bar & Tabs */}
          <div className="bg-white p-4 rounded-2xl border border-zinc-200/80 shadow-2xs space-y-4">
            <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
              {/* Status Tabs */}
              <div className="flex items-center gap-1.5 p-1 bg-zinc-100 rounded-xl">
                <button
                  onClick={() => setActiveTab("pending")}
                  className={cn(
                    "px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all flex items-center gap-1.5",
                    activeTab === "pending"
                      ? "bg-white text-zinc-950 shadow-xs"
                      : "text-zinc-500 hover:text-zinc-950"
                  )}
                >
                  <Sparkles className="w-3.5 h-3.5 text-amber-500" />
                  Flywheel Queue
                  {stats && stats.pending_count > 0 && (
                    <span className="ml-1 bg-amber-100 text-amber-800 text-[10px] px-1.5 py-0.2 rounded-full font-bold">
                      {stats.pending_count}
                    </span>
                  )}
                </button>
                <button
                  onClick={() => setActiveTab("approved")}
                  className={cn(
                    "px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all flex items-center gap-1.5",
                    activeTab === "approved"
                      ? "bg-white text-zinc-950 shadow-xs"
                      : "text-zinc-500 hover:text-zinc-950"
                  )}
                >
                  <CheckCircle2 className="w-3.5 h-3.5 text-emerald-600" />
                  Approved Skills
                </button>
                <button
                  onClick={() => setActiveTab("all")}
                  className={cn(
                    "px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all",
                    activeTab === "all"
                      ? "bg-white text-zinc-950 shadow-xs"
                      : "text-zinc-500 hover:text-zinc-950"
                  )}
                >
                  All ({stats?.total_skills ?? 0})
                </button>
                <button
                  onClick={() => setActiveTab("rejected")}
                  className={cn(
                    "px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all",
                    activeTab === "rejected"
                      ? "bg-white text-zinc-950 shadow-xs"
                      : "text-zinc-500 hover:text-zinc-950"
                  )}
                >
                  Rejected
                </button>
              </div>

              {/* Search */}
              <div className="relative w-full md:w-72">
                <Search className="w-4 h-4 text-zinc-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <Input
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Filter skills or aliases..."
                  className="pl-9 h-9 text-xs rounded-xl bg-zinc-50 border-zinc-200 focus:bg-white"
                />
              </div>
            </div>

            {/* Category Filter Pills */}
            <div className="flex items-center gap-1.5 overflow-x-auto pb-1 text-xs">
              <span className="text-[11px] font-bold text-zinc-400 uppercase mr-1">
                Category:
              </span>
              {CATEGORIES.map((cat) => (
                <button
                  key={cat.id}
                  onClick={() => setSelectedCategory(cat.id)}
                  className={cn(
                    "px-3 py-1 rounded-full text-xs font-medium shrink-0 transition-colors border",
                    selectedCategory === cat.id
                      ? "bg-zinc-950 text-white border-zinc-950"
                      : "bg-zinc-50 text-zinc-600 border-zinc-200 hover:bg-zinc-100"
                  )}
                >
                  {cat.label}
                </button>
              ))}
            </div>
          </div>

          {/* Skills Grid */}
          {loading ? (
            <div className="bg-white rounded-2xl border border-zinc-200 p-12 text-center text-xs text-zinc-500 font-medium">
              Loading skill ontology & flywheel records...
            </div>
          ) : skills.length === 0 ? (
            <div className="bg-white rounded-2xl border border-dashed border-zinc-200 p-12 text-center space-y-3">
              <div className="w-12 h-12 rounded-full bg-zinc-100 text-zinc-400 flex items-center justify-center mx-auto">
                <Layers className="w-6 h-6" />
              </div>
              <h3 className="font-bold text-sm text-zinc-900">No skills matching filter</h3>
              <p className="text-xs text-zinc-500 max-w-sm mx-auto">
                {activeTab === "pending"
                  ? "All candidate skills have been reviewed and normalized into canonical taxonomy entries."
                  : "No skills matched your search query or category filter."}
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {skills.map((skill) => (
                <div
                  key={skill.id}
                  className={cn(
                    "bg-white rounded-2xl border p-5 shadow-2xs flex flex-col justify-between space-y-4 transition-all hover:border-zinc-300",
                    skill.status === "pending"
                      ? "border-amber-200 bg-amber-50/10"
                      : skill.status === "rejected"
                      ? "border-zinc-200 opacity-60"
                      : "border-zinc-200/80"
                  )}
                >
                  <div className="space-y-2.5">
                    {/* Top Row: Name & Category */}
                    <div className="flex items-start justify-between gap-2">
                      <div>
                        <div className="flex items-center gap-2">
                          <h3 className="font-bold text-sm text-zinc-950 leading-snug">
                            {skill.canonical_name}
                          </h3>
                          {skill.is_ambiguous && (
                            <Badge
                              variant="outline"
                              className="text-[9px] font-mono bg-zinc-100 text-zinc-600 px-1.5 py-0 border-zinc-300"
                              title="Ambiguity Guard: Exact match only (never fuzzy)"
                            >
                              Exact Match
                            </Badge>
                          )}
                        </div>
                        <span className="text-[11px] text-zinc-400 font-medium">
                          Source: {skill.source || "lightcast"}
                        </span>
                      </div>

                      <Badge
                        variant="outline"
                        className={cn(
                          "text-[10px] font-semibold px-2 py-0.5 rounded-full capitalize shrink-0 border",
                          getCategoryBadgeColor(skill.category)
                        )}
                      >
                        {skill.category.replace("_", " ")}
                      </Badge>
                    </div>

                    {/* Pending Context Sample */}
                    {skill.status === "pending" && (
                      <div className="p-2.5 bg-amber-50 rounded-xl border border-amber-200/60 text-[11px] text-amber-900 space-y-1">
                        <div className="flex items-center gap-1 font-semibold text-[10px] text-amber-700 uppercase tracking-wider">
                          <Sparkles className="w-3 h-3 text-amber-500" />
                          Extracted from Resumes ({skill.occurrence_count}x)
                        </div>
                        {skill.context_sample && (
                          <p className="italic text-amber-800 line-clamp-2">
                            &ldquo;{skill.context_sample}&rdquo;
                          </p>
                        )}
                      </div>
                    )}

                    {/* Aliases Tags */}
                    <div className="space-y-1">
                      <span className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider">
                        Aliases ({skill.aliases?.length || 0}):
                      </span>
                      <div className="flex flex-wrap gap-1">
                        {skill.aliases && skill.aliases.length > 0 ? (
                          skill.aliases.map((alias, idx) => (
                            <span
                              key={idx}
                              className="text-[11px] font-mono bg-zinc-100 text-zinc-700 px-2 py-0.5 rounded-md border border-zinc-200/60"
                            >
                              {alias}
                            </span>
                          ))
                        ) : (
                          <span className="text-[11px] text-zinc-400 italic">No aliases recorded</span>
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Actions Footer */}
                  <div className="pt-3 border-t border-zinc-100 flex items-center justify-between">
                    {skill.status === "pending" ? (
                      <div className="flex items-center gap-2 w-full">
                        <Button
                          size="sm"
                          onClick={() => handleApprove(skill)}
                          className="flex-1 h-8 text-xs font-semibold rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white transition-colors"
                        >
                          <CheckCircle2 className="w-3.5 h-3.5 mr-1" />
                          Approve Skill
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => handleReject(skill)}
                          className="h-8 px-3 text-xs font-medium rounded-lg border-zinc-200 text-zinc-600 hover:text-rose-600 hover:border-rose-200 transition-colors"
                        >
                          <XCircle className="w-3.5 h-3.5" />
                        </Button>
                      </div>
                    ) : (
                      <div className="flex items-center justify-between w-full text-xs">
                        <span className="text-zinc-400 text-[11px] font-mono">
                          v{skill.taxonomy_version}
                        </span>
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => setAliasModalTarget(skill)}
                          className="h-7 px-2.5 text-xs text-zinc-600 hover:text-zinc-950 font-semibold flex items-center gap-1"
                        >
                          <Tag className="w-3 h-3 text-zinc-400" />
                          + Add Alias
                        </Button>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </main>
      </div>

      {/* Add Canonical Skill Modal */}
      <Dialog open={isAddModalOpen} onOpenChange={setIsAddModalOpen}>
        <DialogContent className="sm:max-w-md bg-white rounded-2xl p-6">
          <DialogHeader>
            <DialogTitle className="font-serif font-black text-lg text-zinc-950">
              Add Canonical Skill
            </DialogTitle>
            <DialogDescription className="text-xs text-zinc-500">
              Define a new standardized skill entry with category and alias mappings.
            </DialogDescription>
          </DialogHeader>

          <form onSubmit={handleCreateSkill} className="space-y-4 mt-2">
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-zinc-700">Canonical Name</label>
              <Input
                value={newCanonicalName}
                onChange={(e) => setNewCanonicalName(e.target.value)}
                placeholder="e.g. Apache Cassandra"
                required
                className="h-9 text-xs rounded-xl"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-zinc-700">Category</label>
              <select
                value={newCategory}
                onChange={(e) => setNewCategory(e.target.value)}
                className="w-full h-9 text-xs rounded-xl border border-zinc-200 px-3 bg-white text-zinc-900 focus:outline-hidden"
              >
                <option value="language">Programming Language</option>
                <option value="framework">Framework</option>
                <option value="database">Database</option>
                <option value="platform">Cloud & Platform</option>
                <option value="tool">Tool & DevOps</option>
                <option value="library">Library & AI/ML</option>
                <option value="domain">Domain & Architecture</option>
                <option value="soft_skill">Soft Skill</option>
              </select>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-zinc-700">
                Aliases (Comma-Separated)
              </label>
              <Input
                value={newAliases}
                onChange={(e) => setNewAliases(e.target.value)}
                placeholder="e.g. cassandra, apache-cassandra, datastax"
                className="h-9 text-xs rounded-xl font-mono"
              />
            </div>

            <div className="flex items-center gap-2 pt-1">
              <input
                type="checkbox"
                id="isAmbiguous"
                checked={newIsAmbiguous}
                onChange={(e) => setNewIsAmbiguous(e.target.checked)}
                className="rounded border-zinc-300 text-black focus:ring-black"
              />
              <label htmlFor="isAmbiguous" className="text-xs text-zinc-700 font-medium">
                Ambiguous Acronym (Requires exact match protection)
              </label>
            </div>

            <DialogFooter className="pt-3">
              <Button
                type="button"
                variant="outline"
                onClick={() => setIsAddModalOpen(false)}
                className="text-xs rounded-full"
              >
                Cancel
              </Button>
              <Button
                type="submit"
                className="text-xs rounded-full bg-black hover:bg-zinc-800 text-white font-semibold"
              >
                Create Skill
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Add Alias Modal */}
      <Dialog open={!!aliasModalTarget} onOpenChange={(open) => !open && setAliasModalTarget(null)}>
        <DialogContent className="sm:max-w-sm bg-white rounded-2xl p-6">
          <DialogHeader>
            <DialogTitle className="font-serif font-black text-base text-zinc-950">
              Add Alias to {aliasModalTarget?.canonical_name}
            </DialogTitle>
            <DialogDescription className="text-xs text-zinc-500">
              Add an alternative name or abbreviation candidates use on resumes.
            </DialogDescription>
          </DialogHeader>

          <form onSubmit={handleAddAliasSubmit} className="space-y-4 mt-2">
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-zinc-700">New Alias String</label>
              <Input
                value={newAliasInput}
                onChange={(e) => setNewAliasInput(e.target.value)}
                placeholder="e.g. k8s-operator"
                required
                className="h-9 text-xs rounded-xl font-mono"
              />
            </div>

            <DialogFooter className="pt-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => setAliasModalTarget(null)}
                className="text-xs rounded-full"
              >
                Cancel
              </Button>
              <Button
                type="submit"
                className="text-xs rounded-full bg-black hover:bg-zinc-800 text-white font-semibold"
              >
                Add Alias
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import {
  Sparkles,
  AlertTriangle,
  MessageSquareCode,
  MoreVertical,
  ArrowUpRight,
  Send,
  Bold,
  Paperclip,
  Code2,
  Workflow,
  Users2,
} from "lucide-react";
import { Progress } from "@/components/ui/progress";
import { Button } from "@/components/ui/button";
import { CandidateDetail, TeamNote, CitationLocation } from "@/types/ats";
import { addCandidateNote, locateCandidateCitation, getErrorMessage } from "@/lib/api";

const CATEGORY_ICONS: Record<string, React.ElementType> = {
  "Technical Depth": Code2,
  "System Design": Workflow,
  Leadership: Users2,
};

interface AIScorecardTabProps {
  candidate: CandidateDetail;
  onSelectCitation?: (citation: CitationLocation) => void;
}

export function AIScorecardTab({ candidate, onSelectCitation }: AIScorecardTabProps) {
  const { scorecard } = candidate;
  const [error, setError] = useState<string | null>(null);
  const [notes, setNotes] = useState<TeamNote[]>(scorecard.team_notes || []);
  const [newNoteText, setNewNoteText] = useState("");
  const [isSubmittingNote, setIsSubmittingNote] = useState(false);

  const handleSendNote = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newNoteText.trim()) return;

    setIsSubmittingNote(true);
    try {
      const added = await addCandidateNote(candidate.id, newNoteText);
      setNotes(previous => [...previous, added]);
      setError(null);
      setNewNoteText("");
    } finally {
      setIsSubmittingNote(false);
    }
  };

  const handleCitationClick = async (cat: typeof scorecard.categories[0]) => {
    if (!onSelectCitation || !cat.quote) return;
    try {
      const result = cat.citation_location ? { found: true, location: cat.citation_location } : await locateCandidateCitation(candidate.id, cat.quote);
      if (!result.found || !result.location) { setError("This quote could not be located in the original resume."); return; }
      setError(null);
      onSelectCitation({ ...result.location, category_name: cat.name });
    } catch (reason) { setError(getErrorMessage(reason)); }
  };

  return (
    <div className="space-y-6">
      {error && <p role="alert" className="text-sm text-red-700">{error}</p>}
      {/* 1. Top Match Gauge Card */}
      <div className="bg-white rounded-2xl border border-zinc-200/80 p-6 shadow-xs flex items-center justify-between gap-6">
        <div className="flex items-center gap-6">
          {/* Circular Score Gauge */}
          <div className="relative w-20 h-20 flex items-center justify-center shrink-0">
            <svg className="w-full h-full -rotate-90" viewBox="0 0 100 100">
              <circle
                cx="50"
                cy="50"
                r="40"
                className="stroke-zinc-100"
                strokeWidth="9"
                fill="transparent"
              />
              <circle
                cx="50"
                cy="50"
                r="40"
                className="stroke-black"
                strokeWidth="9"
                strokeDasharray={2 * Math.PI * 40}
                strokeDashoffset={
                  2 * Math.PI * 40 -
                  ((scorecard.overall_match_score ?? 0) / 100) * (2 * Math.PI * 40)
                }
                strokeLinecap="round"
                fill="transparent"
              />
            </svg>
            <span className="absolute font-bold text-2xl text-zinc-950">
              {scorecard.overall_match_score ?? "—"}
            </span>
          </div>

          {/* Title & Telemetry */}
          <div>
            <h3 className="text-lg font-bold text-zinc-950">
              {scorecard.overall_match_score === null ? `Evaluation ${scorecard.evaluation_status || "pending"}` : scorecard.match_tier}
            </h3>
            <div className="flex items-center gap-2 text-xs text-zinc-500 font-medium mt-1">
              <span className="flex items-center gap-1 font-mono">
                <Sparkles className="w-3 h-3 text-zinc-600" />
                {scorecard.model_version}
              </span>
              <span>•</span>
              <span>{scorecard.evaluated_at}</span>
            </div>
          </div>
        </div>

        <button
          title="More options"
          className="p-1.5 rounded-lg text-zinc-400 hover:text-zinc-800 hover:bg-zinc-100 transition-colors"
        >
          <MoreVertical className="w-4 h-4" />
        </button>
      </div>

      {/* 2. Category Dimension Breakdown Cards */}
      <div className="space-y-4">
        {scorecard.categories.map((cat) => {
          const Icon = CATEGORY_ICONS[cat.name] || Code2;
          const scorePercent = cat.max_score > 0 ? (cat.score / cat.max_score) * 100 : 0;

          return (
            <div
              key={cat.name}
              className="bg-white rounded-2xl border border-zinc-200/80 p-5 shadow-xs space-y-3 hover:border-zinc-300 transition-colors"
            >
              {/* Category Header with Score & Progress Bar */}
              <div className="flex items-center justify-between gap-4">
                <div className="flex items-center gap-2 text-xs font-bold text-zinc-900">
                  <Icon className="w-4 h-4 text-zinc-600" />
                  <span>{cat.name}</span>
                </div>

                <div className="flex items-center gap-3 flex-1 max-w-xs justify-end">
                  <div className="w-40">
                    <Progress value={scorePercent} className="h-1.5 bg-zinc-100" />
                  </div>
                  <span className="text-xs font-bold text-zinc-950 shrink-0 font-mono">
                    {cat.score}
                  </span>
                </div>
              </div>

              {/* Verbatim quote or description with interactive highlighting */}
              {cat.quote && (
                <div className="bg-zinc-50/80 rounded-xl p-3.5 border border-zinc-200/80 space-y-2.5">
                  <p className="text-xs text-zinc-700 italic leading-relaxed font-normal">
                    &ldquo;{cat.quote}&rdquo;
                  </p>
                  <div className="flex items-center justify-between pt-1 border-t border-zinc-200/60">
                    <button
                      onClick={() => handleCitationClick(cat)}
                      className="inline-flex items-center gap-1.5 text-[11px] font-bold text-amber-950 bg-amber-100/90 hover:bg-amber-200/90 border border-amber-300 px-2.5 py-1 rounded-lg transition-all shadow-2xs cursor-pointer group"
                    >
                      <Sparkles className="w-3 h-3 text-amber-700 group-hover:scale-110 transition-transform" />
                      <span>Locate in Resume</span>
                      <ArrowUpRight className="w-3 h-3 text-amber-800" />
                    </button>

                    <span className="text-[10px] text-zinc-400 font-mono">
                      Verify source location
                    </span>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* 3. Risk Flags & Suggested Questions Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Risk Flags */}
        <div className="bg-[#fff7f7] rounded-2xl border border-red-200/80 p-5 shadow-xs space-y-3">
          <div className="flex items-center gap-2 text-[11px] font-bold tracking-wider text-red-600 uppercase">
            <AlertTriangle className="w-4 h-4" />
            <span>RISK FLAGS</span>
          </div>
          <div className="space-y-2">
            {scorecard.risk_flags.map((risk, i) => (
              <p
                key={i}
                className="text-xs text-zinc-800 leading-relaxed font-normal"
              >
                • {risk}
              </p>
            ))}
          </div>
        </div>

        {/* Suggested Improvements / Areas for Improvement */}
        <div className="bg-white rounded-2xl border border-zinc-200/80 p-5 shadow-xs space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2 text-[11px] font-bold tracking-wider text-zinc-800 uppercase">
              <Sparkles className="w-4 h-4 text-amber-600" />
              <span>AREAS FOR IMPROVEMENT</span>
            </div>
            <span className="text-[10px] text-zinc-500 font-medium bg-zinc-100 px-2 py-0.5 rounded-full border border-zinc-200/60">
              Role & Resume Gap
            </span>
          </div>
          <div className="space-y-2.5">
            {((scorecard.suggested_improvements && scorecard.suggested_improvements.length > 0)
              ? scorecard.suggested_improvements
              : scorecard.suggested_questions
            ).map((item, i) => (
              <div
                key={i}
                className="text-xs text-zinc-700 leading-relaxed font-normal flex items-start gap-2 p-2 bg-zinc-50/60 rounded-lg border border-zinc-100"
              >
                <span className="font-semibold text-zinc-900 shrink-0 select-none">
                  {item.match(/^\d+\./) ? "" : `${i + 1}.`}
                </span>
                <span className="flex-1">{item}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* 4. Team Notes Section */}
      <div className="bg-white rounded-2xl border border-zinc-200/80 p-6 shadow-xs space-y-5">
        <span className="text-[11px] font-bold text-zinc-500 tracking-wider uppercase block">
          TEAM NOTES
        </span>

        {/* Existing Comments */}
        <div className="space-y-4">
          {notes.map((note) => (
            <div key={note.id} className="flex items-start gap-3">
              <div className="w-8 h-8 rounded-full bg-black text-white flex items-center justify-center font-bold text-xs shrink-0">
                {note.initials}
              </div>
              <div className="space-y-1 flex-1">
                <div className="flex items-baseline gap-2">
                  <span className="font-bold text-xs text-zinc-950">
                    {note.author}
                  </span>
                  <span className="text-[11px] text-zinc-400 font-medium">
                    {note.timestamp}
                  </span>
                </div>
                <p className="text-xs text-zinc-700 leading-relaxed">
                  {note.content.split("@Sarah").map((part, i, arr) => (
                    <React.Fragment key={i}>
                      {part}
                      {i < arr.length - 1 && (
                        <span className="bg-zinc-100 font-semibold px-1 py-0.5 rounded text-zinc-950">
                          @Sarah
                        </span>
                      )}
                    </React.Fragment>
                  ))}
                </p>
              </div>
            </div>
          ))}
        </div>

        {/* Rich Note Input Form */}
        <form onSubmit={handleSendNote} className="space-y-2 pt-2">
          <div className="border border-zinc-200 rounded-xl overflow-hidden focus-within:ring-2 focus-within:ring-zinc-950">
            <textarea
              value={newNoteText}
              onChange={(e) => setNewNoteText(e.target.value)}
              placeholder="Add a note or @mention someone..."
              rows={2}
              className="w-full p-3 text-xs text-zinc-900 focus:outline-none resize-none leading-relaxed placeholder:text-zinc-400"
            />
            <div className="flex items-center justify-between px-3 py-2 bg-zinc-50/60 border-t border-zinc-100">
              <div className="flex items-center gap-2 text-zinc-400">
                <button
                  type="button"
                  className="hover:text-zinc-800 p-1 rounded transition-colors"
                >
                  <Bold className="w-3.5 h-3.5" />
                </button>
                <button
                  type="button"
                  className="hover:text-zinc-800 p-1 rounded transition-colors"
                >
                  <Paperclip className="w-3.5 h-3.5" />
                </button>
              </div>
              <Button
                type="submit"
                size="sm"
                disabled={!newNoteText.trim() || isSubmittingNote}
                className="h-7 px-3 text-xs font-semibold rounded-lg bg-zinc-950 hover:bg-zinc-800 text-white hover:text-zinc-300 transition-colors"
              >
                <Send className="w-3 h-3 mr-1" />
                <span>Post Note</span>
              </Button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { ArrowLeft, ArrowRight, XCircle, CheckCircle2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { CandidateDetail } from "@/types/ats";

interface CandidateHeaderProps {
  candidate: CandidateDetail;
  onStageChange?: (newStage: string) => void;
}

export function CandidateHeader({
  candidate,
  onStageChange,
}: CandidateHeaderProps) {
  const currentStage = candidate.stage || "Contacted";

  const handleAdvance = () => {
    const nextStage = currentStage === "Interviewing" ? "Negotiation" : "Offered";
    if (onStageChange) onStageChange(nextStage);
  };

  const handleReject = () => {
    if (onStageChange) onStageChange("Rejected");
  };

  return (
    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-6 border-b border-zinc-200/80">
      {/* Left: Breadcrumbs + Title + Metadata */}
      <div>
        <div className="flex items-center gap-2 text-xs font-medium text-zinc-500 mb-2">
          <Link
            href={candidate.applied_for_job_id ? `/jobs/${candidate.applied_for_job_id}` : "/jobs"}
            className="flex items-center gap-1 hover:text-zinc-900 transition-colors"
          >
            <ArrowLeft className="w-3.5 h-3.5" />
            <span>Jobs</span>
          </Link>
          <span>›</span>
          <Link
            href={candidate.applied_for_job_id ? `/jobs/${candidate.applied_for_job_id}` : "/jobs"}
            className="text-zinc-700 hover:text-zinc-950 font-semibold truncate max-w-sm"
          >
            {candidate.applied_for_job}
          </Link>
        </div>

        <div className="flex items-center gap-3">
          <h1 className="text-2xl font-bold text-zinc-950 tracking-tight">
            {candidate.name}
          </h1>
          <span className="inline-flex items-center gap-1.5 bg-zinc-100 text-zinc-800 text-xs font-semibold px-3 py-1 rounded-full border border-zinc-200">
            <span className="w-1.5 h-1.5 rounded-full bg-zinc-900" />
            {currentStage}
          </span>
        </div>

        <p className="text-xs text-zinc-500 font-medium mt-1">
          {candidate.role} • Applied {candidate.applied_date}
        </p>
      </div>

      {/* Right: Actions */}
      <div className="flex items-center gap-3">
        <Button
          variant="pillOutline"
          size="sm"
          onClick={handleReject}
          className="text-xs px-4 border-zinc-300 hover:bg-zinc-100"
        >
          Reject
        </Button>
        <Button
          variant="pill"
          size="sm"
          onClick={handleAdvance}
          className="text-xs px-5 gap-1.5 shadow-sm"
        >
          <span>Advance Stage</span>
          <ArrowRight className="w-3.5 h-3.5" />
        </Button>
      </div>
    </div>
  );
}

import React from "react";
import {
  MapPin,
  Mail,
  Phone,
  Link2,
  Briefcase,
  GraduationCap,
  Sparkles,
  ShieldCheck,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { CandidateDetail } from "@/types/ats";

interface CandidateLeftPanelProps {
  candidate: CandidateDetail;
}

export function CandidateLeftPanel({ candidate }: CandidateLeftPanelProps) {
  return (
    <div className="space-y-6">
      {/* Top Profile Card */}
      <div className="bg-white rounded-2xl border border-zinc-200/80 p-6 shadow-xs flex flex-col items-center text-center">
        {/* Large Avatar or Initials Badge */}
        <div className="relative mb-4">
          {candidate.avatar && candidate.avatar.startsWith("http") ? (
            <img
              src={candidate.avatar}
              alt={candidate.name}
              className="w-28 h-28 rounded-full object-cover border-4 border-white shadow-md"
            />
          ) : (
            <div className="w-28 h-28 rounded-full bg-gradient-to-br from-zinc-800 to-zinc-950 text-white flex items-center justify-center font-bold text-2xl border-4 border-white shadow-md tracking-wider">
              {candidate.avatar ||
                candidate.name
                  .split(" ")
                  .map((p) => p[0])
                  .join("")
                  .slice(0, 2)
                  .toUpperCase()}
            </div>
          )}
        </div>

        {/* Name & Headline */}
        <h2 className="font-bold text-lg text-zinc-950">{candidate.name}</h2>
        <div className="flex items-center gap-1.5 text-xs text-zinc-500 font-medium mt-1">
          <MapPin className="w-3.5 h-3.5 text-zinc-400" />
          <span>{candidate.location && candidate.location !== "N/A" ? candidate.location : "N/A"}</span>
        </div>

        {/* Contact Links */}
        <div className="w-full mt-6 pt-6 border-t border-zinc-100 space-y-3 text-left">
          <div className="flex items-center gap-3 text-xs text-zinc-600 font-medium">
            <Mail className="w-4 h-4 text-zinc-400 shrink-0" />
            {candidate.email && candidate.email !== "N/A" ? (
              <a
                href={`mailto:${candidate.email}`}
                className="hover:text-zinc-950 transition-colors truncate"
              >
                {candidate.email}
              </a>
            ) : (
              <span className="text-zinc-400 font-normal">N/A</span>
            )}
          </div>

          <div className="flex items-center gap-3 text-xs text-zinc-600 font-medium">
            <Phone className="w-4 h-4 text-zinc-400 shrink-0" />
            {candidate.phone && candidate.phone !== "N/A" ? (
              <a
                href={`tel:${candidate.phone}`}
                className="hover:text-zinc-950 transition-colors"
              >
                {candidate.phone}
              </a>
            ) : (
              <span className="text-zinc-400 font-normal">N/A</span>
            )}
          </div>

          <div className="flex items-center gap-3 text-xs text-zinc-600 font-medium">
            <Link2 className="w-4 h-4 text-zinc-400 shrink-0" />
            {candidate.linkedin && candidate.linkedin !== "N/A" ? (
              <a
                href={candidate.linkedin.startsWith("http") ? candidate.linkedin : `https://${candidate.linkedin}`}
                target="_blank"
                rel="noreferrer"
                className="hover:text-zinc-950 transition-colors truncate"
              >
                {candidate.linkedin}
              </a>
            ) : (
              <span className="text-zinc-400 font-normal">N/A</span>
            )}
          </div>
        </div>
      </div>

      {/* Experience Timeline Card */}
      <div className="bg-white rounded-2xl border border-zinc-200/80 p-6 shadow-xs space-y-5">
        <span className="text-[11px] font-bold text-zinc-500 tracking-wider uppercase block">
          EXPERIENCE
        </span>

        <div className="space-y-6 relative before:absolute before:left-1.5 before:top-2 before:bottom-2 before:w-[2px] before:bg-zinc-100">
          {candidate.experience.map((exp, idx) => (
            <div key={idx} className="relative pl-6 space-y-1">
              {/* Dot */}
              <div
                className={`absolute left-0 top-1.5 w-3.5 h-3.5 rounded-full border-2 border-white ${
                  idx === 0 ? "bg-black" : "bg-zinc-300"
                }`}
              />
              <div className="flex items-baseline justify-between gap-2">
                <h4 className="font-bold text-xs text-zinc-900 leading-tight">
                  {exp.role}, {exp.company}
                </h4>
              </div>
              <span className="text-[11px] text-zinc-400 font-medium block">
                {exp.period}
              </span>
            </div>
          ))}
        </div>

        {/* Education Subtext */}
        {candidate.highest_education && (
          <div className="pt-4 border-t border-zinc-100 flex items-start gap-2 text-xs text-zinc-600">
            <GraduationCap className="w-4 h-4 text-zinc-400 shrink-0 mt-0.5" />
            <span className="font-medium">{candidate.highest_education}</span>
          </div>
        )}

        {/* Core Skills Chips with Context Enrichment */}
        <div className="pt-4 border-t border-zinc-100 space-y-2.5">
          <div className="flex items-center justify-between">
            <span className="text-[11px] font-bold text-zinc-500 tracking-wider uppercase block">
              VERIFIED SKILLS ({candidate.core_skills.length})
            </span>
          </div>
          <div className="flex flex-wrap gap-1.5">
            {candidate.core_skills.map((skill) => {
              const enriched = candidate.enriched_skills?.find(
                (e) => e.canonical_name.toLowerCase() === skill.toLowerCase()
              );
              const isImpact = enriched?.highest_mention_tier === "demonstrated_impact";
              const isDemonstrated = enriched?.highest_mention_tier === "demonstrated";
              const isCert = enriched?.is_certified;
              const isActive = enriched?.is_actively_used;

              return (
                <div
                  key={skill}
                  className={`inline-flex items-center gap-1 text-[11px] px-2.5 py-0.5 rounded-md font-medium border transition-colors ${
                    isImpact
                      ? "bg-emerald-50 text-emerald-900 border-emerald-200/80 shadow-2xs"
                      : isDemonstrated
                      ? "bg-sky-50 text-sky-900 border-sky-200/80"
                      : isCert
                      ? "bg-amber-50 text-amber-900 border-amber-200/80"
                      : "bg-zinc-50 text-zinc-800 border-zinc-200/70"
                  }`}
                  title={
                    enriched
                      ? `Tier: ${enriched.highest_mention_tier.replace("_", " ")} | Weight: ${enriched.max_evidence_weight}x | Status: ${isActive ? "Active in current role" : enriched.last_used_date || "Demonstrated"}`
                      : skill
                  }
                >
                  {isImpact && <Sparkles className="w-2.5 h-2.5 text-emerald-600 shrink-0" />}
                  {isCert && !isImpact && <ShieldCheck className="w-2.5 h-2.5 text-amber-600 shrink-0" />}
                  {isActive && <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 shrink-0" />}
                  <span>{skill}</span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

