export function PipelineKanban({ pipeline, onAddCandidate }: PipelineKanbanProps) {
  const stages = [
    { key: "Contacted", label: "Contacted" },
    { key: "Interview", label: "Interview" },
    { key: "Negotiation", label: "Negotiation" },
  ];

  return (
    <div className="mt-8 font-sans">
      {/* Header Row */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2.5">
          <span className="w-1.5 h-5 rounded-full bg-black shrink-0" />
          <h2 className="text-xl font-bold text-zinc-900 tracking-tight">
            Pipeline Overview
          </h2>
        </div>
        <Button
          onClick={onAddCandidate}
          size="sm"
          className="gap-1.5 text-xs font-semibold px-4 h-9 bg-black hover:bg-zinc-800 text-white hover:text-zinc-300 rounded-full transition-all shadow-xs cursor-pointer"
        >
          <Plus className="w-3.5 h-3.5 stroke-[2.5]" />
          <span>Add Candidate</span>
        </Button>
      </div>

      {/* Kanban Columns Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
        {stages.map(({ key, label }) => {
          const items = pipeline[key] || [];

          return (
            <div
              key={key}
              className="bg-[#f6f5f1] rounded-2xl p-4 flex flex-col gap-3 min-h-[360px]"
            >
              {/* Column Header */}
              <div className="flex items-center justify-between px-1 pb-1">
                <span className="font-bold text-xs text-zinc-800">{label}</span>
                <span className="w-5 h-5 rounded-full bg-[#eae7df] text-zinc-700 font-bold text-[11px] flex items-center justify-center">
                  {items.length}
                </span>
              </div>

              {/* Candidate Cards */}
              <div className="flex flex-col gap-3">
                {items.length === 0 ? (
                  <div className="p-8 text-center text-xs text-zinc-400 border border-dashed border-zinc-200/80 rounded-xl bg-white/40">
                    No candidates in {label.toLowerCase()}
                  </div>
                ) : (
                  items.map((candidate) => {
                    const isNegotiation = key === "Negotiation";

                    return (
                      <Link
                        key={candidate.id}
                        href={`/candidates/${candidate.id}`}
                        className="block group"
                      >
                        <div
                          className="bg-white rounded-xl p-4 shadow-xs hover:border-zinc-400 hover:shadow-md transition-all duration-200 flex flex-col gap-3 relative overflow-hidden border border-zinc-200/80"
                        >
                          {/* Top Row: Avatar + Name + Score Badge */}
                          <div className="flex items-start justify-between gap-2">
                            <div className="flex items-center gap-3">
                              {candidate.avatar && typeof candidate.avatar === "string" && candidate.avatar.startsWith("http") ? (
                                <img
                                  src={candidate.avatar}
                                  alt={candidate.name || "Candidate"}
                                  className="w-10 h-10 rounded-full object-cover border border-zinc-200/80 shrink-0"
                                />
                              ) : (
                                <div className="w-10 h-10 rounded-full bg-[#eae7df] text-zinc-800 font-bold text-xs flex items-center justify-center shrink-0">
                                  {candidate.avatar || (candidate.name ? candidate.name.split(" ").map(n => n[0]).join("").slice(0, 2).toUpperCase() : "CD")}
                                </div>
                              )}
                              <div className="flex flex-col">
                                <span className="font-bold text-xs text-zinc-950 group-hover:text-black">
                                  {candidate.name || "Candidate"}
                                </span>
                                <span className="text-[11px] text-zinc-500 font-medium leading-tight">
                                  {candidate.role || "Software Specialist"}
                                </span>
                              </div>
                            </div>

                            {/* Match Score Badge */}
                            <div
                              className={cn(
                                "flex items-center gap-1 px-2 py-0.5 rounded-lg text-xs font-bold shrink-0 relative",
                                isNegotiation
                                  ? "bg-black text-white"
                                  : "bg-zinc-50 border border-zinc-200 text-zinc-900"
                              )}
                            >
                              <Target
                                className={cn(
                                  "w-3 h-3 stroke-[2]",
                                  isNegotiation ? "text-white" : "text-zinc-700"
                                )}
                              />
                              <span>{candidate.match_score ?? "Pending"}</span>
                            </div>
                          </div>

                          {/* Summary / screening note */}
                          <p className="text-[11px] text-zinc-600 line-clamp-2 leading-relaxed">
                            {candidate.summary}
                          </p>

                          {/* Probability bar for Negotiation */}
                          {candidate.probability !== null &&
                            candidate.probability !== undefined && (
                              <div className="flex items-center gap-3 pt-2">
                                <div className="flex-1 bg-zinc-200 h-1.5 rounded-full overflow-hidden">
                                  <div
                                    style={{ width: `${candidate.probability}%` }}
                                    className="h-full bg-black rounded-full"
                                  />
                                </div>
                                <span className="text-[11px] font-medium text-zinc-500 shrink-0">
                                  {candidate.probability}% prob
                                </span>
                              </div>
                            )}
                        </div>
                      </Link>
                    );
                  })
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import React from "react";
import {
  ShoppingBag,
  Users,
  Timer,
  Award,
  TrendingUp,
  TrendingDown,
  Ticket,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { StatMetric } from "@/types/ats";

const ICON_MAP: Record<string, React.ElementType> = {
  briefcase: ShoppingBag,
  shoppingBag: ShoppingBag,
  users: Users,
  clock: Timer,
  timer: Timer,
  award: Ticket,
  ticket: Ticket,
};

export function StatCard({ metric }: { metric: StatMetric }) {
  const Icon = ICON_MAP[metric.icon] || ShoppingBag;
  const isDark = metric.style === "highlighted_dark";

  return (
    <div
      className={cn(
        "rounded-2xl p-6 transition-all duration-200 shadow-xs relative flex flex-col justify-between min-h-[155px] font-sans",
        isDark
          ? "bg-black text-white"
          : "bg-white text-zinc-950 border border-zinc-200/70"
      )}
    >
      {/* Header Row */}
      <div className="flex items-start justify-between">
        <span
          className={cn(
            "text-[11px] font-bold tracking-wider uppercase leading-tight",
            isDark ? "text-zinc-400" : "text-zinc-500",
            metric.id === "avg_time_to_hire" && "max-w-[100px]"
          )}
        >
          {metric.id === "avg_time_to_hire" ? (
            <>
              AVG TIME-TO-
              <br />
              HIRE
            </>
          ) : (
            metric.label
          )}
        </span>
        <div
          className={cn(
            "w-8 h-8 rounded-full flex items-center justify-center shrink-0",
            isDark ? "bg-zinc-800 text-zinc-300" : "bg-[#f2ece1] text-zinc-700"
          )}
        >
          <Icon className="w-4 h-4 stroke-[1.8]" />
        </div>
      </div>

      {/* Main Metric Value */}
      <div className="mt-1 flex items-baseline gap-1.5">
        <span className="text-3xl font-bold tracking-tight">{metric.value}</span>
        {metric.unit && (
          <span
            className={cn(
              "text-sm font-medium",
              isDark ? "text-zinc-400" : "text-zinc-900"
            )}
          >
            {metric.unit}
          </span>
        )}
      </div>

      {/* Trend / Subtext */}
      <div className="mt-2 flex items-center gap-1.5 text-xs">
        {metric.trend === "positive" && (
          <TrendingUp
            className={cn(
              "w-3.5 h-3.5 stroke-[2]",
              isDark ? "text-emerald-400" : "text-zinc-700"
            )}
          />
        )}
        {metric.trend === "negative" && (
          <TrendingDown className="w-3.5 h-3.5 text-zinc-700 stroke-[2]" />
        )}
        <span
          className={cn(
            "font-medium",
            isDark ? "text-zinc-300 text-xs" : "text-zinc-600 text-xs"
          )}
        >
          {metric.change}
        </span>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import {
  Bold,
  Italic,
  Underline,
  List,
  ListOrdered,
  Link2,
  Sparkles,
  Plus,
  X,
  ChevronDown,
} from "lucide-react";
import { createJobRequisition } from "@/lib/api";
import { JobRequisition } from "@/types/ats";

interface CreateJobModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onJobCreated?: (job: JobRequisition) => void;
}

export function CreateJobModal({
  open,
  onOpenChange,
  onJobCreated,
}: CreateJobModalProps) {
  const [title, setTitle] = useState("Senior Backend Engineer");
  const [department, setDepartment] = useState("Engineering");
  const [location, setLocation] = useState("Remote");
  const [description, setDescription] = useState(
    `We are seeking an experienced Senior Backend Engineer to join our core platform team. You will be responsible for designing, building, and maintaining scalable microservices that power our primary application.\n\nKey Responsibilities:\n• Architect high-performance APIs\n• Optimize database queries and schema design`
  );
  const [skills, setSkills] = useState([
    "Python",
    "FastAPI",
    "PostgreSQL",
    "Kubernetes",
  ]);
  const [newSkillInput, setNewSkillInput] = useState("");
  const [isAddingSkill, setIsAddingSkill] = useState(false);
  const [runAiMatch, setRunAiMatch] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleAddSkill = () => {
    if (newSkillInput.trim() && !skills.includes(newSkillInput.trim())) {
      setSkills([...skills, newSkillInput.trim()]);
      setNewSkillInput("");
      setIsAddingSkill(false);
    }
  };

  const handleRemoveSkill = (skillToRemove: string) => {
    setSkills(skills.filter((s) => s !== skillToRemove));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      const created = await createJobRequisition({
        title,
        department,
        location,
        job_description: description,
        required_skills: skills,
        run_ai_match: runAiMatch,
      });
      if (onJobCreated) onJobCreated(created);
      onOpenChange(false);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-xl p-7 rounded-2xl bg-white border border-zinc-200 shadow-2xl">
        <DialogHeader>
          <DialogTitle className="text-xl font-bold text-zinc-950">
            Create New Job
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-5 mt-2">
          {/* Job Title */}
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-zinc-600">
              Job Title
            </label>
            <Input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="e.g. Senior Backend Engineer"
              className="h-10 rounded-xl bg-white border-zinc-200 text-sm font-medium"
              required
            />
          </div>

          {/* Department & Location Row */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-zinc-600">
                Department
              </label>
              <div className="relative">
                <select
                  value={department}
                  onChange={(e) => setDepartment(e.target.value)}
                  className="w-full h-10 px-3 pr-8 rounded-xl border border-zinc-200 bg-white text-sm font-medium text-zinc-900 appearance-none focus:outline-none focus:ring-2 focus:ring-zinc-950"
                >
                  <option value="Engineering">Engineering</option>
                  <option value="Data">Data</option>
                  <option value="Design">Design</option>
                  <option value="Product">Product</option>
                  <option value="Marketing">Marketing</option>
                </select>
                <ChevronDown className="w-4 h-4 text-zinc-400 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-zinc-600">
                Location
              </label>
              <div className="relative">
                <select
                  value={location}
                  onChange={(e) => setLocation(e.target.value)}
                  className="w-full h-10 px-3 pr-8 rounded-xl border border-zinc-200 bg-white text-sm font-medium text-zinc-900 appearance-none focus:outline-none focus:ring-2 focus:ring-zinc-950"
                >
                  <option value="Remote">Remote</option>
                  <option value="New York / Hybrid">New York / Hybrid</option>
                  <option value="London / Remote">London / Remote</option>
                  <option value="San Francisco / Hybrid">
                    San Francisco / Hybrid
                  </option>
                </select>
                <ChevronDown className="w-4 h-4 text-zinc-400 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
              </div>
            </div>
          </div>

          {/* Job Description with Rich Text Toolbar */}
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-zinc-600">
              Job Description
            </label>
            <div className="border border-zinc-200 rounded-xl overflow-hidden focus-within:ring-2 focus-within:ring-zinc-950">
              {/* Toolbar */}
              <div className="flex items-center gap-1 px-3 py-1.5 bg-zinc-50 border-b border-zinc-200 text-zinc-600">
                <button
                  type="button"
                  className="p-1 rounded hover:bg-zinc-200 transition-colors"
                >
                  <Bold className="w-3.5 h-3.5" />
                </button>
                <button
                  type="button"
                  className="p-1 rounded hover:bg-zinc-200 transition-colors"
                >
                  <Italic className="w-3.5 h-3.5" />
                </button>
                <button
                  type="button"
                  className="p-1 rounded hover:bg-zinc-200 transition-colors"
                >
                  <Underline className="w-3.5 h-3.5" />
                </button>
                <div className="w-[1px] h-4 bg-zinc-300 mx-1" />
                <button
                  type="button"
                  className="p-1 rounded hover:bg-zinc-200 transition-colors"
                >
                  <List className="w-3.5 h-3.5" />
                </button>
                <button
                  type="button"
                  className="p-1 rounded hover:bg-zinc-200 transition-colors"
                >
                  <ListOrdered className="w-3.5 h-3.5" />
                </button>
                <div className="w-[1px] h-4 bg-zinc-300 mx-1" />
                <button
                  type="button"
                  className="p-1 rounded hover:bg-zinc-200 transition-colors"
                >
                  <Link2 className="w-3.5 h-3.5" />
                </button>
              </div>
              {/* Textarea */}
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={5}
                className="w-full p-3 text-xs text-zinc-800 focus:outline-none resize-none leading-relaxed"
                placeholder="Enter key requirements and responsibilities..."
                required
              />
            </div>
          </div>

          {/* Required Skills Section */}
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <label className="text-xs font-semibold text-zinc-600">
                Required Skills
              </label>
              <span className="bg-black text-white text-[10px] font-bold px-2 py-0.5 rounded-full tracking-wider flex items-center gap-1">
                <Sparkles className="w-2.5 h-2.5" />
                AUTO-EXTRACTED
              </span>
            </div>

            <div className="flex flex-wrap items-center gap-2">
              {skills.map((skill) => (
                <div
                  key={skill}
                  className="bg-zinc-100 border border-zinc-200/80 rounded-lg px-2.5 py-1 text-xs font-medium text-zinc-800 flex items-center gap-1.5 group hover:bg-zinc-200/80 transition-colors"
                >
                  <span>{skill}</span>
                  <button
                    type="button"
                    onClick={() => handleRemoveSkill(skill)}
                    className="text-zinc-400 hover:text-zinc-800"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </div>
              ))}

              {isAddingSkill ? (
                <div className="flex items-center gap-1">
                  <Input
                    value={newSkillInput}
                    onChange={(e) => setNewSkillInput(e.target.value)}
                    placeholder="Skill name"
                    className="h-7 w-28 text-xs py-0 px-2 rounded-lg"
                    autoFocus
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        e.preventDefault();
                        handleAddSkill();
                      } else if (e.key === "Escape") {
                        setIsAddingSkill(false);
                      }
                    }}
                  />
                  <Button
                    type="button"
                    size="sm"
                    variant="outline"
                    className="h-7 px-2 text-xs"
                    onClick={handleAddSkill}
                  >
                    Add
                  </Button>
                </div>
              ) : (
                <button
                  type="button"
                  onClick={() => setIsAddingSkill(true)}
                  className="border border-dashed border-zinc-300 hover:border-zinc-500 rounded-lg px-2.5 py-1 text-xs font-medium text-zinc-600 hover:text-zinc-950 flex items-center gap-1 transition-colors"
                >
                  <Plus className="w-3 h-3" />
                  <span>Add skill</span>
                </button>
              )}
            </div>
          </div>

          {/* AI Match Toggle Card */}
          <div className="bg-[#f7f6f2] border border-[#e8e6df] rounded-xl p-3.5 flex items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <Switch
                checked={runAiMatch}
                onCheckedChange={setRunAiMatch}
                id="ai-match-toggle"
              />
              <div>
                <label
                  htmlFor="ai-match-toggle"
                  className="text-xs font-bold text-zinc-900 cursor-pointer block"
                >
                  Run AI Match on save
                </label>
                <p className="text-[11px] text-zinc-500 mt-0.5">
                  Screens all candidates through the 3-stage pipeline. ~60s · Top
                  20 evaluated by LLM
                </p>
              </div>
            </div>
          </div>

          {/* Dialog Action Footer */}
          <div className="flex items-center justify-end gap-3 pt-2">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="h-9 px-4 text-xs font-medium rounded-xl"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="h-9 px-5 text-xs font-semibold rounded-xl bg-gradient-to-r from-[#5046e5] to-[#7c3aed] text-white hover:opacity-95 shadow-md flex items-center gap-1.5"
            >
              <Sparkles className="w-3.5 h-3.5" />
              <span>{isSubmitting ? "Creating..." : "Create & Match"}</span>
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React from "react";
import Link from "next/link";
import {
  Code2,
  Database,
  Palette,
  Briefcase,
  Sparkles,
  Cloud,
  ShieldCheck,
  CheckCircle2,
  Crown,
  Cpu,
  PauseCircle,
  MoreVertical,
  Clock,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { JobRequisition } from "@/types/ats";
import { cn } from "@/lib/utils";

const ICON_MAP: Record<string, React.ElementType> = {
  ai: Sparkles,
  cloud: Cloud,
  database: Database,
  security: ShieldCheck,
  code: Code2,
  design: Palette,
  qa: CheckCircle2,
  leadership: Crown,
  product: Briefcase,
  emerging: Cpu,
};

const DEPT_STYLE_MAP: Record<string, { bg: string; text: string }> = {
  "AI & Intelligent Systems": { bg: "bg-purple-50 border-purple-200/60", text: "text-purple-700" },
  "Cloud & Infrastructure": { bg: "bg-sky-50 border-sky-200/60", text: "text-sky-700" },
  "Data Science & Analytics": { bg: "bg-emerald-50 border-emerald-200/60", text: "text-emerald-700" },
  "Cybersecurity & Risk": { bg: "bg-rose-50 border-rose-200/60", text: "text-rose-700" },
  "Software Engineering": { bg: "bg-blue-50 border-blue-200/60", text: "text-blue-700" },
  "Quality Assurance & Support": { bg: "bg-amber-50 border-amber-200/60", text: "text-amber-700" },
  "Tech Leadership & Strategy": { bg: "bg-indigo-50 border-indigo-200/60", text: "text-indigo-700" },
  "Specialized & Emerging Domains": { bg: "bg-teal-50 border-teal-200/60", text: "text-teal-700" },
};

interface JobCardProps {
  job: JobRequisition;
  onViewPipeline?: (job: JobRequisition) => void;
}

export function JobCard({ job }: JobCardProps) {
  const IconComponent = ICON_MAP[job.icon_type] || Code2;
  const isOpen = job.status === "OPEN";
  const deptStyle = DEPT_STYLE_MAP[job.department] || { bg: "bg-zinc-100/90 border-zinc-200/60", text: "text-zinc-700" };

  return (
    <div className="bg-white rounded-2xl border border-zinc-200/80 p-5 shadow-xs hover:border-zinc-300 hover:shadow-sm transition-all flex flex-col gap-4">
      {/* Top Main Row */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        {/* Left Area: Icon + Job Info */}
        <div className="flex items-start md:items-center gap-4 flex-1 min-w-0">
          {/* Job Type Icon */}
          <div className={cn("w-12 h-12 rounded-xl border flex items-center justify-center shrink-0", deptStyle.bg, deptStyle.text)}>
            <IconComponent className="w-5 h-5" />
          </div>

          {/* Title, Department, Location, Posted Date */}
          <div className="space-y-1 min-w-0">
            <div className="flex items-center gap-2.5 flex-wrap">
              <Link href={`/jobs/${job.id}`}>
                <h3 className="font-bold text-sm text-zinc-950 hover:text-indigo-600 transition-colors cursor-pointer">
                  {job.title}
                </h3>
              </Link>
              <Badge
                variant={isOpen ? "statusOpen" : "statusPaused"}
                className="text-[10px] px-2 py-0.5"
              >
                {job.status}
              </Badge>
              <span className="text-[11px] font-semibold text-zinc-500 bg-zinc-100 px-2 py-0.5 rounded-md">
                {job.department}
              </span>
            </div>

            <div className="flex items-center gap-3 text-xs text-zinc-500 font-medium">
              <span>{job.location}</span>
              <span>•</span>
              <span>{job.min_years_experience}y+ exp</span>
              <span>•</span>
              <span className="text-zinc-400">Posted {job.posted_date}</span>
            </div>
          </div>
        </div>

        {/* Center/Right Area: Candidates + AI Match Status + Action CTA */}
        <div className="flex items-center justify-between md:justify-end gap-5 shrink-0 border-t md:border-t-0 pt-3 md:pt-0 border-zinc-100">
          {/* Candidate Avatars */}
          <div className="flex items-center gap-2 shrink-0">
            <div className="flex -space-x-2 overflow-hidden">
              {(job.avatars || []).slice(0, 3).map((avatarUrl, i) => (
                <img
                  key={i}
                  className="inline-block h-7 w-7 rounded-full ring-2 ring-white object-cover"
                  src={avatarUrl}
                  alt="Candidate"
                />
              ))}
              {(job.candidates_count || 0) > 3 && (
                <div className="flex h-7 w-7 items-center justify-center rounded-full bg-zinc-100 ring-2 ring-white text-[10px] font-bold text-zinc-600">
                  +{(job.candidates_count || 0) - 3}
                </div>
              )}
            </div>
            <span className="text-xs font-semibold text-zinc-700 hidden sm:inline">
              {job.candidates_count || 0}
            </span>
          </div>

          {/* Match Metric */}
          <div className="text-right min-w-[110px]">
            {isOpen && job.top_match && job.top_match.score !== null ? (
              <div className="flex flex-col items-end">
                <div className="flex items-center gap-1 text-xs font-bold text-zinc-950">
                  <Sparkles className="w-3.5 h-3.5 text-indigo-600" />
                  <span>{job.top_match.label || "Top Match"}</span>
                </div>
                <span className="text-[11px] text-zinc-400 font-medium">
                  {job.top_match.last_run || "Active"}
                </span>
              </div>
            ) : (
              <div className="flex flex-col items-end">
                <div className="flex items-center gap-1 text-xs font-semibold text-zinc-500">
                  <PauseCircle className="w-3.5 h-3.5 text-zinc-400" />
                  <span>Paused</span>
                </div>
                <span className="text-[11px] text-zinc-400">-</span>
              </div>
            )}
          </div>

          {/* View Pipeline Button */}
          <div className="flex items-center gap-2">
            <Link href={`/jobs/${job.id}`}>
              <Button
                variant="pillOutline"
                size="sm"
                className="h-8 text-xs font-semibold px-4 rounded-full border-zinc-300 text-zinc-900 bg-white hover:bg-zinc-950 hover:text-white transition-all shadow-none cursor-pointer"
              >
                Pipeline
              </Button>
            </Link>
            <button
              title="Options"
              className="p-1.5 rounded-lg text-zinc-400 hover:text-zinc-800 hover:bg-zinc-100 transition-colors"
            >
              <MoreVertical className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Description Snippet & Required Skills Row */}
      <div className="pt-2 border-t border-zinc-100 flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs">
        <p className="text-zinc-600 line-clamp-1 flex-1 font-normal">
          {job.job_description || "No description provided."}
        </p>
        <div className="flex items-center gap-1.5 flex-wrap shrink-0">
          {(job.required_skills || []).slice(0, 4).map((skill) => (
            <span
              key={skill}
              className="px-2 py-0.5 rounded-md bg-zinc-100/80 text-zinc-700 text-[10px] font-medium"
            >
              {skill}
            </span>
          ))}
          {(job.required_skills || []).length > 4 && (
            <span className="text-[10px] font-semibold text-zinc-400">
              +{(job.required_skills || []).length - 4} more
            </span>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import { Search, ChevronDown, SlidersHorizontal } from "lucide-react";

export const DEPARTMENTS = [
  { id: "ALL", label: "All Departments" },
  { id: "AI & Intelligent Systems", label: "AI, Machine Learning & Systems" },
  { id: "Cloud & Infrastructure", label: "Cloud, DevOps & Infrastructure" },
  { id: "Data Science & Analytics", label: "Data Science, Analytics & Big Data" },
  { id: "Cybersecurity & Risk", label: "Cybersecurity & Risk Management" },
  { id: "Software Engineering", label: "Software Engineering & Digital Design" },
  { id: "Quality Assurance & Support", label: "QA, Automation & IT Support" },
  { id: "Tech Leadership & Strategy", label: "Tech Leadership, Product & Strategy" },
  { id: "Specialized & Emerging Domains", label: "Specialized & Emerging Domains" },
];

interface JobFiltersProps {
  search: string;
  onSearchChange: (val: string) => void;
  status: string;
  onStatusChange: (val: string) => void;
  department: string;
  onDepartmentChange: (val: string) => void;
}

export function JobFilters({
  search,
  onSearchChange,
  status,
  onStatusChange,
  department,
  onDepartmentChange,
}: JobFiltersProps) {
  return (
    <div className="bg-white rounded-2xl border border-zinc-200/80 p-3 shadow-xs flex flex-col md:flex-row items-center gap-3">
      {/* Search Input */}
      <div className="relative flex-1 w-full">
        <Search className="w-4 h-4 text-zinc-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
        <input
          type="text"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
          placeholder="Search by job title, department, or required skills (e.g. LLMs, Python, AWS)..."
          className="w-full h-10 pl-10 pr-4 text-xs bg-zinc-50/70 rounded-xl border border-transparent focus:border-zinc-300 focus:bg-white focus:outline-none transition-all placeholder:text-zinc-400"
        />
      </div>

      {/* Filter Dropdowns & Controls */}
      <div className="flex items-center gap-3 w-full md:w-auto">
        {/* Status Dropdown */}
        <div className="relative">
          <select
            value={status}
            onChange={(e) => onStatusChange(e.target.value)}
            className="h-10 pl-3 pr-8 rounded-xl bg-zinc-50/80 border border-zinc-200/70 text-xs font-semibold text-zinc-700 appearance-none focus:outline-none focus:ring-2 focus:ring-zinc-950 cursor-pointer"
          >
            <option value="ALL">Status: All</option>
            <option value="OPEN">Status: Open</option>
            <option value="PAUSED">Status: Paused</option>
            <option value="CLOSED">Status: Closed</option>
          </select>
          <ChevronDown className="w-3.5 h-3.5 text-zinc-400 absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none" />
        </div>

        {/* Department Dropdown */}
        <div className="relative">
          <select
            value={department}
            onChange={(e) => onDepartmentChange(e.target.value)}
            className="h-10 pl-3 pr-8 rounded-xl bg-zinc-50/80 border border-zinc-200/70 text-xs font-semibold text-zinc-700 appearance-none focus:outline-none focus:ring-2 focus:ring-zinc-950 cursor-pointer max-w-[200px] truncate"
          >
            {DEPARTMENTS.map((dept) => (
              <option key={dept.id} value={dept.id}>
                {dept.label}
              </option>
            ))}
          </select>
          <ChevronDown className="w-3.5 h-3.5 text-zinc-400 absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none" />
        </div>

        {/* Clear Filters Button if any active */}
        {(search || status !== "ALL" || department !== "ALL") && (
          <button
            onClick={() => {
              onSearchChange("");
              onStatusChange("ALL");
              onDepartmentChange("ALL");
            }}
            className="text-xs text-zinc-500 hover:text-zinc-900 font-semibold px-2 py-1 transition-colors"
          >
            Reset
          </button>
        )}
      </div>
    </div>
  );
}
